window.AponarN3Deep = {"lang":"ar","map":{"কোনো কাজ বা পরিবর্তনের “শুরুর সীমানা” দেখায়। 始める-এর আগে যে verb থাকে, সেটিই শুরু হওয়া কাজ; তাই 読み始める মানে “পড়া নামের কাজ শুরু করা”।":"يحدد «حد البداية» لفعل أو تغيير. الفعل الذي يأتي قبل 始める هو الفعل الذي يبدأ؛ لذا 読み始める تعني «بدء الفعل المسمى القراءة».","ইচ্ছাকৃত কাজ ও ধীরে শুরু হওয়া প্রাকৃতিক ঘটনা—দুই ক্ষেত্রেই চলে। তবে 結婚する・死ぬ-এর মতো এক মুহূর্তে সম্পূর্ণ হওয়া verb-এর সঙ্গে সাধারণত অস্বাভাবিক শোনায়।":"يعمل مع الأفعال المتعمدة ومع الأحداث الطبيعية التي تبدأ تدريجيا على حد سواء. لكن مع الأفعال التي تكتمل في لحظة واحدة، مثل 結婚する・死ぬ، يبدو عادة غير طبيعي.","～出す-এ হঠাৎ/অপ্রত্যাশিত শুরুর ঝাঁকুনি আছে; ～始める নিরপেক্ষ। ～続ける শুরু নয়, শুরু হওয়ার পর একই কাজ চলতে থাকা বোঝায়।":"لدى ～出す هزة بداية مفاجئة/غير متوقعة؛ ～始める محايدة. أما ～続ける فليست عن البداية — تعني أن الفعل نفسه يستمر بعد أن يبدأ.","মোবাইলের START বোতাম চাপার ছবি মনে করো: ます বাদ → কাজের নাম → 始める। 読みます → 読み始める।":"تخيل الضغط على زر START على هاتف: أسقط ます → اسم الفعل → 始める. 読みます → 読み始める.","“আমি গত মাস থেকে N3 পড়া শুরু করেছি”—নিজের তথ্য দিয়ে একটি বাক্য বলো।":"«بدأت دراسة N3 الشهر الماضي» — قل جملة باستخدام معلوماتك الخاصة.","অন্য কেউ যে নির্দেশ দিয়েছে, সেটিকে হুবহু quote না করে “কী করতে বলেছে” হিসেবে জানায়। ように-এর আগের অংশ হলো নির্দেশের content, に-marked ব্যক্তি হলো নির্দেশদাতা।":"يُبلغ عن تعليمة أعطاها شخص آخر، ليس كاقتباس دقيق، بل كـ «ما قيل لي أن أفعله». الجزء قبل ように هو محتوى التعليمة، والشخص المحدد بـ に هو من أعطاها.","辞書形 হলে করতে বলা, ない形 হলে না করতে বলা। নিজের ইচ্ছা নয়; বাইরে থেকে পাওয়া নির্দেশ, অনুরোধ বা সতর্কতা বোঝায়।":"مع صيغة القاموس تعني أن يُقال لك أن تفعل شيئا؛ ومع صيغة ない، أن يُقال لك ألا تفعل. ليست رغبتك الخاصة — تنقل تعليمة، أو طلبا، أو تحذيرا متلقى من الخارج.","「早く来て」と言われた হলো সরাসরি quote; 早く来るように言われた হলো একই কথার indirect report। সাধারণ বক্তব্যের ということ-এর সঙ্গে গুলিও না।":"「早く来て」と言われた اقتباس مباشر؛ 早く来るように言われた هي التقرير غير المباشر للكلمات نفسها. لا تخلط بينها وبين ということ، التي هي للعبارات العادية.","先生 → ように → 私—একটি তীরের ছবি: শিক্ষকের কথা ように দিয়ে তোমার দিকে এসেছে।":"先生 → ように → 私 — تخيل سهما: كلمات المعلم تأتي إليك عبر ように.","স্কুলে শিক্ষক তোমাকে যে একটি কাজ করতে বলেছেন, ように言われました দিয়ে বলো।":"قل شيئا واحدا قال لك معلمك في المدرسة أن تفعله، باستخدام ように言われました.","একটি পুরো বাক্যকে “একটি তথ্য/ঘটনা” নামের noun-box-এ ঢোকায়। তাই বাক্যটির পরে を知る・が分かる・は大切だ ইত্যাদি বসতে পারে।":"يضع جملة كاملة داخل صندوق اسم يسمى «حقيقة/حدث». لذا بعد الجملة يمكنك إرفاق を知る・が分かる・は大切だ وهكذا.","কেবল অনুবাদে “যে” দেখলেই নয়—পরের অংশে তথ্যটিকে noun হিসেবে ধরার প্রয়োজন আছে কি না দেখো। N/なA-এর present affirmative-এ だということ হয়।":"لا تقرر فقط لأن الترجمة تُظهر «أن» — تحقق مما إذا كان الجزء التالي يحتاج إلى معاملة تلك المعلومة كاسم. بالنسبة للأسماء وصفات な في الإثبات الحاضر، تصبح だということ.","～ということです শোনা তথ্য জানাতেও ব্যবহৃত হয়; ～ということ শুধু nominalizer হতে পারে। ～の／こと-ও noun বানায়, কিন্তু ということ-এ “এই মর্মের তথ্য” ভাব স্পষ্ট।":"تُستخدم ～ということです أيضا لنقل معلومات مسموعة؛ أما ～ということ فيمكن أن تكون مجرد أداة اسمية. كما تجعل ～の／こと الأشياء أسماء، لكن ということ توضح معنى «معلومات مفادها أن…».","ということ-কে “তথ্যের বাক্স” ভাবো: পুরো sentence ঢুকল, বাইরে একটি noun বের হলো।":"فكر في ということ كـ «صندوق حقائق»: تدخل جملة كاملة، ويخرج اسم واحد.","“আগামীকাল পরীক্ষা নেই—এই কথা জানতাম না” ということを知らなかった দিয়ে বলো।":"«لا يوجد امتحان غدا — لم أكن أعرف ذلك» — قلها باستخدام ということを知らなかった.","দেখা তথ্য বা নিজের বিচার থেকে ভবিষ্যৎ/অজানা বিষয়ে সম্ভাব্য সিদ্ধান্ত জানায়: “সম্ভবত এমন হবে—এটাই আমার ধারণা।”":"من معلومات ملحوظة أو من حكمك الخاص، يعطي استنتاجا محتملا عن المستقبل أو شيء غير معروف: «من المحتمل أن يكون هكذا — هذا تخميني».","だろう বক্তব্যকে অনুমান বানায়, と思う সেটিকে ব্যক্তিগত মত হিসেবে নরম করে। দৃঢ় প্রমাণভিত্তিক はず বা に違いない-এর চেয়ে অনিশ্চয়তা বেশি।":"だろう يحول العبارة إلى تخمين، وと思う يخففها كرأي شخصي. تحمل عدم يقين أكثر من はず أو に違いない القائمين على الأدلة.","～かと思います আরও ভদ্র ও নরম; ～に違いない অনেক দৃঢ়; ～そうだ যদি চেহারা দেখে তাৎক্ষণিক অনুমান হয়।":"～かと思います أكثر تهذيبا ولطفا؛ ～に違いない أكثر حزما بكثير؛ ～そうだ لتخمين فوري من مظهر شيء ما.","মাথার ভেতর মেঘ: だろう = “হয়তো”, 思う = “আমি ভাবি”—দুইটি একসাথে হলে নম্র অনুমান।":"سحابة داخل رأسك: だろう = «ربما»، 思う = «أعتقد» — معا يصنعان تخمينا متواضعا.","আগামীকালের আবহাওয়া নিয়ে だろうと思います ব্যবহার করে একটি অনুমান বলো।":"اصنع تخمينا عن طقس الغد باستخدام だろうと思います.","চোখে দেখা লক্ষণ থেকে কোনো কাজ “হবে বলে মনে হচ্ছে না” বোঝায়। এটি negative appearance; বাস্তব সত্য বা শোনা খবর নয়।":"من علامات مرئية، تعني أن فعلا «لا يبدو أنه سيحدث». هذا مظهر سلبي — ليس حقيقة فعلية أو أخبارا مسموعة.","Vない-এর শেষ い ফেলে なさそう: 行かない→行かなさそう。 いい-এর negative হলো よくない→よくなさそう; ない নিজে adjective হলে なさそう হয়।":"أسقط الـ い الأخيرة من صيغة Vない وأضف なさそう: 行かない→行かなさそう. نفي いい هو よくない→よくなさそう؛ وعندما تكون ない نفسها هي الصفة، تصبح なさそう.","降りそう = দেখে মনে হচ্ছে পড়বে; 降らなさそう = মনে হচ্ছে পড়বে না; 降るそうだ = শুনেছি পড়বে। Form বদলালে source বদলে যায়।":"降りそう = يبدو أنه سيسقط (مطر)؛ 降らなさそう = لا يبدو أنه سيسقط؛ 降るそうだ = سمعت أنه سيسقط. غيّر الشكل فيتغير المصدر.","ない-এর い দরজায় রেখে দাও, তারপর さそう ঢোকাও: 行かな＋さそう।":"اترك الـ い من ない عند الباب، ثم دع さそう يدخل: 行かな＋さそう.","খাবারের ছবি দেখে “এটা ঝাল হবে বলে মনে হচ্ছে না” なさそう দিয়ে বলো।":"بالنظر إلى صورة طعام، قل «هذا لا يبدو أنه سيكون حارا» باستخدام なさそう.","A কাজ করার সঙ্গে সঙ্গে B-তে নতুন কিছু দেখা, বোঝা বা আবিষ্কার হলো। A হলো discovery-র দরজা; B সাধারণত past state/event।":"بمجرد أن تفعل A، ترى، أو تدرك، أو تكتشف شيئا جديدا في B. A هو باب الاكتشاف؛ B عادة حالة أو حدث ماض.","A-এর পরে নিজের ইচ্ছামতো পরিকল্পিত কাজ বসানো যায় না। 開けると、雪が降っていた স্বাভাবিক; 開けると、買い物に行った অস্বাভাবিক, কারণ দ্বিতীয়টি নিজের সিদ্ধান্ত।":"بعد A لا يمكنك وضع فعل مخطط له بإرادتك الخاصة. 開けると、雪が降っていた طبيعية؛ 開けると、買い物に行った غير طبيعية، لأن الجزء الثاني هو قرارك الخاص.","～たとたん-এ আকস্মিক ঘটনার shock; ～と、～た-তে “করতেই দেখলাম/জানলাম” discovery। ～たら-তে শর্ত বা আবিষ্কার দুটোই হতে পারে।":"لدى ～たとたん صدمة حدث مفاجئ؛ ～と、～た هي اكتشاف «عندما فعلت ذلك، رأيت/عرفت». مع ～たら يمكن أن تكون إما شرطا أو اكتشافا.","দরজা খোলার ছবি: 開けると… ক্যামেরার সামনে নতুন দৃশ্য দেখা গেল—তাই পরের অংশ past।":"تخيل فتح باب: 開けると… يظهر مشهد جديد أمام الكاميرا — لذلك الجزء التالي في الماضي.","“স্টেশনে পৌঁছে দেখলাম ট্রেন চলে গেছে”—discovery pattern দিয়ে বলো।":"«عندما وصلت إلى المحطة، وجدت أن القطار قد غادر بالفعل» — قلها بنمط الاكتشاف.","কোনো অবস্থা সাধারণ সীমা ছাড়িয়ে কতটা তীব্র, তা একটি ফল/অসম্ভব অবস্থার মাধ্যমে মাপে: “এত… যে…”।":"يقيس مدى شدة حالة ما، بما يتجاوز الحد الطبيعي، عبر نتيجة أو حالة مستحيلة: «جدا لدرجة أن…».","ほど-এর আগের clause হলো মাত্রার মাপকাঠি; পরে মূল অবস্থা। বাস্তব সংখ্যা নয়, অনুভূতির scale। Positive ও negative—দুটিতেই আসতে পারে।":"العبارة قبل ほど هي مقياس الدرجة؛ الحالة الرئيسية تأتي بعدها. ليس رقما فعليا — إنه مقياس شعور. يمكن أن يظهر في سياقات إيجابية وسلبية على حد سواء.","～くらい-ও মাত্রা দেয় এবং কথ্যতর; ほど তুলনা/মাত্রায় একটু নিরপেক্ষ। ～ほど…ない আলাদা comparison structure।":"تعطي ～くらい أيضا درجة وهي أكثر عامية؛ ほど أكثر حيادية بقليل للمقارنة/الدرجة. أما ～ほど…ない فهي بنية مقارنة منفصلة.","থার্মোমিটারের লাল দাগ সীমা ছাড়িয়েছে—যে ফল দেখে মাত্রা বোঝা যায়, সেই ফলের আগে ほど।":"الخط الأحمر على مقياس حرارة تجاوز الحد — ほど تأتي قبل النتيجة التي يمكنك من خلالها معرفة الدرجة.","আজকের ক্লান্তি “দাঁড়াতে পারছি না এত…” এই কাঠামোয় বলো।":"قل تعب اليوم بهذه البنية: «متعب جدا لدرجة أنني لا أستطيع حتى الوقوف…».","সময়রেখায় “এখন” থেকে সামনে চলা কাজ বা পরিবর্তন দেখায়। いく এখানে শুধু শারীরিকভাবে যাওয়া নয়; ভবিষ্যতের দিকে এগোনোর arrow।":"على خط زمني، يُظهر فعلا أو تغييرا يتقدم من «الآن». いく هنا ليست مجرد ذهاب مادي؛ إنها سهم يتقدم نحو المستقبل.","দীর্ঘমেয়াদি পরিকল্পনা, সামাজিক পরিবর্তন, অভ্যাস চালিয়ে যাওয়া—এসব ক্ষেত্রে স্বাভাবিক। চলার দিক বক্তার বর্তমান সময়/স্থান থেকে দূরে।":"هي طبيعية للخطط طويلة الأجل، والتغيرات الاجتماعية، والحفاظ على العادات. اتجاه الحركة بعيدا عن وقت/مكان المتكلم الحاضر.","～てくる = অতীত থেকে এখন পর্যন্ত পরিবর্তন বা দূর থেকে কাছে; ～ていく = এখন থেকে ভবিষ্যৎ বা কাছ থেকে দূরে।":"～てくる = تغيير من الماضي حتى الآن، أو من بعيد إلى قريب؛ ～ていく = من الآن إلى المستقبل، أو من قريب إلى بعيد.","NOW |——→ FUTURE; arrow-এর মাথায় いく লিখে রাখো।":"NOW |——→ FUTURE؛ اكتب いく في رأس السهم.","“এখন থেকে প্রতিদিন জাপানি পড়তে থাকব” ～ていきます দিয়ে বলো।":"«من الآن فصاعدا سأواصل دراسة اليابانية كل يوم» — قلها باستخدام ～ていきます.","একই কাজ থামানো ছাড়া বা নিয়মিতভাবে চালিয়ে যাওয়ার continuity দেখায়। আগে কাজ শুরু হয়েছে—এখন তার রেখা লম্বা হচ্ছে।":"يُظهر استمرارية فعل الفعل نفسه دون توقف، أو بانتظام. الفعل بدأ بالفعل — الآن خطه يطول.","সময় ধরে চলতে পারে এমন durative verb-এর সঙ্গে ভালো চলে। একবারেই শেষ হওয়া瞬間動詞-এর সঙ্গে বিশেষ context ছাড়া চলে না।":"يعمل بشكل جيد مع الأفعال الدائمة التي يمكن أن تستمر مع مرور الوقت. مع الأفعال اللحظية (瞬間動詞) التي تنتهي في لحظة واحدة، لا يعمل بدون سياق خاص.","～ている বর্তমান চলমান অবস্থা দেখায়; ～続ける “থামিনি/চালিয়ে গেছি” জোর দেয়। ～ていく ভবিষ্যৎ দিকও যোগ করে।":"تُظهر ～ている حالة جارية حالية؛ تؤكد ～続ける «لم أتوقف / واصلت». تضيف ～ていく أيضا اتجاها مستقبليا.","ます কেটে verb-কে একটি লম্বা রেললাইনে বসাও: 勉強し＋続ける।":"اقطع ます وضع الفعل على خط سكة حديد طويل: 勉強し＋続ける.","তুমি কত মাস ধরে কাজ/পড়াশোনা চালিয়ে যাচ্ছ—続けています দিয়ে বলো।":"قل كم شهرا واصلت عملك/دراستك، باستخدام 続けています.","শ্রোতার বলা তথ্য বা ধরে নেওয়া পরিস্থিতিকে topic বানিয়ে তার ভিত্তিতে পরামর্শ, প্রস্তাব বা সহায়তা দেয়।":"يأخذ ما قاله المستمع، أو موقفا مفترضا، كموضوع، وعلى هذا الأساس يعطي نصيحة، أو اقتراحا، أو عرض مساعدة.","AならB-তে B সাধারণত বক্তার judgement। N ও なA-এর だ বাদ যায়: 学生なら、静かなら।":"في AならB، B عادة حكم المتكلم. تسقط だ من الأسماء وصفات な: 学生なら、静かなら.","～たら সাধারণ “যদি/যখন”; ～なら “যেহেতু তুমি A বলছ/যদি A-ই হয়”। ～と automatic result-এ বেশি, advice-এ নয়।":"～たら هي «إذا/عندما» العامة؛ ～なら هي «بما أنك تقول A / إذا كان A هو الحال». أما ～と فتُستخدم أكثر للنتائج التلقائية، لا للنصيحة.","বন্ধু বলল “新宿へ行く”; তুমি তার কথাটি তুলে নিলে—行くなら、この電車。":"قال صديقك «新宿へ行く»؛ تلتقط كلماتهم — 行くなら、この電車。","এক বন্ধু সস্তা রেস্টুরেন্ট খুঁজছে—なら দিয়ে পরামর্শ দাও।":"صديق يبحث عن مطعم رخيص — قدم نصيحة باستخدام なら.","という／と-এর কথ্য short form। নাম ব্যাখ্যা, উদ্ধৃতি, শোনা কথা বা topic—কথোপকথনে দ্রুত সংযোগ করে।":"صيغة قصيرة عامية لـ という／と. تربط بسرعة شروحات الأسماء، والاقتباسات، والنقل المسموع، والمواضيع في المحادثة.","বন্ধু, পরিবার ও casual speech-এ স্বাভাবিক। আবেদনপত্র, রিপোর্ট, শিক্ষককে formal explanation-এ という／と ব্যবহার নিরাপদ।":"هي طبيعية مع الأصدقاء، والعائلة، وفي الكلام العامي. لاستمارات التقديم، والتقارير، والشروحات الرسمية لمعلم، という／と أكثر أمانا.","Nって人 = Nという人; 来ないって言った = 来ないと言った। Rule 38-এর Nって হলো は-এর casual topic—sentence position দেখে কাজ বুঝবে।":"Nって人 = Nという人؛ 来ないって言った = 来ないと言った. أما Nって في القاعدة 38 فهي الموضوع العامي は — احكم على وظيفتها من موقعها في الجملة.","って হলো কথার zip-file: という লম্বা form ছোট হয়ে って হয়েছে।":"って هي ملف مضغوط للكلام: الصيغة الطويلة という انكمشت إلى って.","“JLPT বলতে কী?” এবং “শুনেছি কাল ছুটি”—って দিয়ে দুই রকম বাক্য বলো।":"قل نوعين من الجمل مع って: «ماذا تعني بـ JLPT؟» و«سمعت أن غدا عطلة».","অন্যের অনুমতি/সহযোগিতা পেয়ে বক্তা নিজে কিছু করার সুযোগ পেয়েছে—এই উপকারের দৃষ্টিভঙ্গি দেখায়।":"يُظهر أنه، بإذن شخص آخر أو تعاونه، حصل المتكلم على فرصة لفعل شيء بنفسه — وجهة نظر تلقي معروف هذه.","যিনি অনুমতি দিয়েছেন তাঁকে に দিয়ে চিহ্নিত করা যায়। もらう-তে অনুমতি পাওয়া ও কৃতজ্ঞতার অনুভূতি আছে; শুধু নিজের সিদ্ধান্ত নয়।":"يمكن تحديد الشخص الذي أعطى الإذن بـ に. もらう تحمل معنى تلقي الإذن والامتنان؛ ليست مجرد قرارك الخاص.","～させていただく আরও বিনয়ী ও formal; ～てもらう-তে অন্য ব্যক্তি সরাসরি কাজটি করে দেয়, কিন্তু させてもらう-তে কাজটি বক্তাই করে।":"～させていただく أكثر تواضعا ورسمية؛ في ～てもらう يفعل شخص آخر الفعل لك مباشرة، لكن في させてもらう يفعل المتكلم الفعل بنفسه.","Causative させる দরজা খুলল, もらう সেই অনুমতি “পাওয়া”—তারপর আমি কাজ করি।":"السببي させる فتح الباب، もらう هي «تلقي» ذلك الإذن — ثم أفعل الفعل.","ম্যানেজারের অনুমতিতে আগে বাড়ি ফিরেছ—させてもらいました দিয়ে বলো।":"عدت إلى البيت مبكرا بإذن مديرك — قلها باستخدام させてもらいました.","কেউ আমাকে জোর করে কাজ করিয়েছে—causative + passive একসঙ্গে। Subject হলো বাধ্য হওয়া ব্যক্তি, に-marked ব্যক্তি বাধ্যকারী।":"أجبرني شخص على فعل شيء — سببي + مبني للمجهول معا. الفاعل هو الشخص الذي أُجبر؛ والشخص المحدد بـ に هو من أجبرهم.","সাধারণত অনিচ্ছা, কষ্ট বা অসন্তোষ থাকে। Group 1-এ 行く→行かせられる/কথ্য 行かされる; Group 2-এ 食べさせられる।":"عادة يوجد تردد، أو مشقة، أو عدم رضا. في المجموعة 1، 行く→行かせられる / عاميا 行かされる؛ في المجموعة 2، 食べさせられる.","させる = করানো/করতে দেওয়া; られる = করা হলো; させられる = করাতে বাধ্য করা হলো। ～ように言われた নির্দেশ পেয়েছি, কিন্তু বাস্তবে বাধ্য হয়ে করেছি—এ জোর নেই।":"させる = جعل/ترك شخص يفعل؛ られる = أن يُجعل لفعل؛ させられる = أن يُجبر على الفعل. أما ～ように言われた فتعني قيل لي أن أفعل، لكنها تفتقر إلى قوة «لم يكن لدي خيار سوى فعله في النهاية».","দুই তালা: させ (করানো) + られる (আমার ওপর হলো) = বাধ্য হলাম।":"قفلان: させ (جعل شخص يفعل) + られる (فُعل بي) = أُجبرت.","ছোটবেলায় এমন একটি কাজ যা তোমাকে জোর করে করানো হতো, させられました দিয়ে বলো।":"قل شيئا واحدا أُجبرت على فعله كطفل، باستخدام させられました.","নিজের অনুভূতি নয়—অন্য ব্যক্তির বাইরে দেখা আচরণ থেকে “সে এমন অনুভব করছে” বোঝায়। 感情 adjective-কে observable action বানায়।":"ليست مشاعرك الخاصة — من سلوك شخص آخر الخارجي، تُظهر «يبدو أنهم يشعرون هكذا». تحول صفات العاطفة إلى أفعال قابلة للملاحظة.","私-এর সরাসরি অনুভূতিতে সাধারণত うれしい／怖い বলি; তৃতীয় ব্যক্তিতে うれしがっている／怖がっている। ～たい→～たがる-ও একই দৃষ্টিভঙ্গি।":"لمشاعري المباشرة الخاصة أقول عادة うれしい／怖い؛ لشخص ثالث، うれしがっている／怖がっている. أما ～たい→～たがる فتتبع وجهة النظر نفسها.","～そうだ appearance হতে পারে কিন্তু মুহূর্তের impression; ～がる আচরণের মাধ্যমে অনুভূতির pattern। ～と思っている হলে তার চিন্তা জানা/উদ্ধৃত।":"يمكن أن تكون ～そうだ مظهرا، لكنها انطباع لحظي؛ ～がる نمط شعور يظهر عبر السلوك. أما ～と思っている فتعني أن أفكارهم معروفة/مقتبسة.","হৃদয় দেখা যায় না, আচরণ দেখা যায়—অন্যের হৃদয়ের ওপর “がる ক্যামেরা” বসাও।":"لا يمكنك رؤية القلب، لكن يمكنك رؤية السلوك — ضع «كاميرا がる» على قلب شخص آخر.","এক শিশু কুকুর দেখে ভয় পাচ্ছে—怖がっています দিয়ে বলো।":"طفل خائف من كلب — قلها باستخدام 怖がっています.","A শেষ হওয়ার ঠিক মুহূর্তেই B হঠাৎ ঘটে। সময়ের ফাঁক প্রায় শূন্য এবং B সাধারণত অনিয়ন্ত্রিত/অপ্রত্যাশিত।":"في اللحظة الدقيقة التي ينتهي فيها A، يحدث B فجأة. الفجوة الزمنية تكاد تكون صفرا، وB عادة غير مسيطر عليه/غير متوقع.","B-তে বক্তার ইচ্ছা, আদেশ বা পরিকল্পনা সাধারণত আসে না। একই ঘটনার স্বাভাবিক ধারাবাহিকতা নয়—surprise দরকার।":"عادة لا تحتوي B على إرادة المتكلم، أو أوامر، أو خطط. ليست الاستمرار الطبيعي للحدث نفسه — مفاجأة مطلوبة.","～と、～た discovery-তে নতুন কিছু দেখা যায়; ～たとたん shock-এর মুহূর্ত। ～たらより সময়ের আকস্মিকতা অনেক শক্ত।":"في ～と、～た (اكتشاف) يُرى شيء جديد؛ ～たとたん هي لحظة الصدمة. فجائيتها الزمنية أقوى بكثير من ～たら.","দরজা বন্ধ—“টান!” শব্দ—সঙ্গে সঙ্গে আলো নিভে গেল। “টান” = とたん।":"أُغلق الباب — «بام!» — وفي اللحظة نفسها انطفأ الضوء. ذلك «البام» = とたん.","বাইরে বের হতেই বৃষ্টি শুরু হলো—たとたん দিয়ে বলো।":"في اللحظة التي خرجت فيها، بدأت تمطر — قلها باستخدام たとたん.","কোনো কাজ/ঘটনা আচমকা ফেটে শুরু হওয়া বোঝায়। Verb-stem + 出す যেন ভিতরের action হঠাৎ বাইরে বেরিয়ে এল।":"يُظهر فعلا أو حدثا ينفجر فجأة إلى بداية. جذع الفعل + 出す كأن الفعل الداخلي خرج فجأة إلى الخارج.","泣き出す・笑い出す・降り出す-এর মতো sudden onset-এ খুব স্বাভাবিক। বক্তার শান্ত পরিকল্পিত শুরুতে 始める বেশি নিরপেক্ষ।":"هو طبيعي جدا للبدايات المفاجئة مثل 泣き出す・笑い出す・降り出す. لبداية المتكلم الهادئة والمخططة، 始める أكثر حيادية.","読み始める = পড়া শুরু করা; 泣き出す = হঠাৎ কেঁদে ওঠা। “হঠাৎ” অনুভূতি না থাকলে 出す বেছে নিও না।":"読み始める = أن تبدأ القراءة؛ 泣き出す = أن تنفجر فجأة في البكاء. إذا لم يوجد شعور «فجأة»، لا تختر 出す.","বাক্সের ভেতর থেকে action “বের হলো”—出す-এর kanji-ই memory picture।":"الفعل «خرج» من داخل الصندوق — كانجي 出す نفسه هو صورة الذاكرة.","ক্লাসে সবাই হঠাৎ হাসতে শুরু করল—笑い出した দিয়ে বলো।":"بدأ الجميع في الفصل يضحكون فجأة — قلها باستخدام 笑い出した.","意向形 দিয়ে action-এর ঠিক আগের প্রস্তুতি/চেষ্টা ধরে: “করতে যাচ্ছিল/করার চেষ্টা করছে।” কাজটি শেষ হয়েছে কি না নিশ্চিত নয়।":"باستخدام 意向形 (صيغة الإرادة)، يلتقط التحضير/المحاولة قبل الفعل مباشرة: «كان على وشك أن يفعل / يحاول أن يفعل». ليس مؤكدا ما إذا كان الفعل قد اكتمل.","～ようとしたが… হলে চেষ্টা ব্যর্থ হওয়ার গল্পে বেশি আসে। Non-volitional subject-এ imminent change-ও হতে পারে: 日が沈もうとしている।":"غالبا تظهر ～ようとしたが… في قصص محاولة فاشلة. مع فاعل غير إرادي يمكن أن تكون أيضا تغييرا وشيكا: 日が沈もうとしている.","～つもりだ স্থির পরিকল্পনা; ～ようと思う intention; ～ようとする action শুরুর ঠিক মুহূর্ত বা বাস্তব চেষ্টা।":"～つもりだ خطة ثابتة؛ ～ようと思う نية؛ ～ようとする هي اللحظة الدقيقة قبل بدء الفعل، أو محاولة حقيقية.","দৌড় শুরুর লাইনে পা তুলেছে কিন্তু এখনো ছুটেনি—এই মাঝের frame হলো ようとする।":"عداء عند خط البداية رفع قدما لكنه لم يجر بعد — ذلك الإطار البيني هو ようとする.","ট্রেনে উঠতে যাচ্ছিলে, কিন্তু দরজা বন্ধ হলো—ようとしたとき দিয়ে বলো।":"كنت على وشك ركوب القطار، لكن الأبواب أُغلقت — قلها باستخدام ようとしたとき.","একটি ঘটনা সবসময় নয়, মাঝে মাঝে সম্ভাব্য/বাস্তব হয়—এই exception-কে যোগ করে। も “এমনটাও” ভাব দেয়।":"يضيف استثناء أن حدثا ليس دائما هو الحال، لكنه أحيانا ممكن/فعلي. も تعطي شعور «هذا أيضا، أحيانا».","習慣/সম্ভাবনার ওঠানামায় ব্যবহৃত হয়। অতীতের একবারের ঘটনা বলতে ことがある নয়; Vたことがある experience-এর আলাদা pattern।":"يُستخدم لتقلبات العادات/الاحتمالات. للحديث عن حدث ماض واحد، ليست ことがある؛ أما Vたことがある فهي نمط منفصل للتجربة.","Vることがある = কখনো হয়; Vたことがある = আগে করার অভিজ্ঞতা আছে; Vる可能性がある = formal সম্ভাবনা।":"Vることがある = يحدث أحيانا؛ Vたことがある = لدي تجربة فعل ذلك من قبل؛ Vる可能性がある = احتمال رسمي.","ক্যালেন্ডারের বেশির ভাগ দিন সাদা, দু-একটি দিন রঙিন—সেই “কখনো কখনো”-ই こともある।":"معظم أيام التقويم بيضاء، لكن واحدا أو اثنين ملونان — ذلك «أحيانا» هو こともある.","ব্যস্ত হলে তুমি কখনো নাশতা না করেও বের হও—こともあります দিয়ে বলো।":"عندما تكون مشغولا، تغادر أحيانا دون تناول الإفطار — قلها باستخدام こともあります.","কাউকে কোনো কাজ করতে দেওয়া/করিয়ে আগাম অবস্থা তৈরি করে রাখা। させる agent বদলায়, ておく future preparation যোগ করে।":"جعل شخص يفعل فعلا، أو تركه يفعله، وخلق حالة مجهزة مسبقا. させる تغير الفاعل؛ ておく تضيف تحضيرا مستقبليا.","অনুমতি ও নির্দেশ—দুই reading context-এ সম্ভব: 子どもを遊ばせておく = শিশুকে খেলতে দিয়ে রাখা; 部下に準備させておく = কর্মীকে প্রস্তুত করিয়ে রাখা।":"كلتا القراءتين — إذن وتعليمة — ممكنتان حسب السياق: 子どもを遊ばせておく = دع الطفل يواصل اللعب؛ 部下に準備させておく = اجعل مرؤوسا يحضر (واتركه جاهزا).","～ておく-এ subject নিজে প্রস্তুতি করে; ～させておく-এ অন্য কাউকে করায়/করতে দেয়। ～させてもらう-তে আমি অনুমতি পাই।":"في ～ておく يحضر الفاعل ذلك بنفسه؛ في ～させておく يجعل شخصا آخر يفعله / يدع شخصا يفعله. في ～させてもらう، أتلقى إذنا.","আগামীকালের জন্য একটি মানুষকে “action অবস্থায় রেখে দাও”—させ + ておく।":"اترك شخصا «في وضع الفعل» جاهزا للغد — させ + ておく.","মিটিংয়ের আগে সহকর্মীকে কাগজ প্রস্তুত করিয়ে রাখবে—বাক্য বানাও।":"قبل الاجتماع، ستجعل زميلا يحضر الوثائق ويتركها جاهزة — اصنع جملة.","অন্যের action আমার ওপর passive হয়ে এসেছে এবং てしまう সেটিকে অনিচ্ছাকৃত ক্ষতি/দুঃখ হিসেবে সম্পূর্ণ করেছে।":"جاء فعل شخص آخر علي في المبني للمجهول، وてしまう تكمله كخسارة/حزن غير راغب.","শুধু passive fact নয়; বক্তার affected feeling গুরুত্বপূর্ণ। 財布を盗まれてしまった-তে চুরি এবং ক্ষতির আফসোস দুটোই আছে।":"ليست مجرد حقيقة مبنية للمجهول؛ شعور المتكلم بالتأثر مهم. في 財布を盗まれてしまった توجد كل من السرقة وندم الخسارة.","盗まれた = চুরি হয়েছে (fact); 盗まれてしまった = চুরি হয়ে গিয়ে বিপদ/দুঃখ হয়েছে। ～てしまう active হলেও ভুল/সম্পূর্ণতা বোঝাতে পারে।":"盗まれた = سُرق (حقيقة)؛ 盗まれてしまった = سُرق وتسبب في مشكلة/حزن. يمكن لـ ～てしまう أيضا أن تُظهر خطأ أو إكمالا في المبني للمعلوم.","Passive-এর ওপর “দুঃখের সিল” しまう লাগাও—られてしまう।":"ضع «ختم الحزن»، しまう، فوق المبني للمجهول — られてしまう.","কেউ তোমার ছাতা নিয়ে যাওয়ায় তুমি সমস্যায় পড়েছ—এই pattern দিয়ে বলো।":"أخذ شخص مظلتك ووُضعت في مشكلة — قلها بهذا النمط.","কোন পদ্ধতি, প্রযুক্তি বা মাধ্যম ব্যবহার করে ফলটি হলো—সেই tool/channel দেখায়। NによるN হলে পরের noun-কে পদ্ধতি অনুযায়ী বর্ণনা করে।":"يُظهر أي طريقة، أو تقنية، أو وسيلة استُخدمت لتحقيق النتيجة — تلك الأداة/القناة. في NによるN، يصف الاسم التالي وفقا للطريقة.","লিখিত ও formal ভাষায় বেশি। মানুষকে intermediary হিসেবে বললে ～を通して বেশি natural হতে পারে; সরাসরি physical tool-এ で সহজ।":"هو أكثر شيوعا في اللغة المكتوبة والرسمية. عند الحديث عن شخص كوسيط، يمكن أن يكون ～を通して أكثر طبيعية؛ أما لأداة مادية مباشرة، فـ で أبسط.","電車で行く = সাধারণ tool; インターネットによる投票 = formal method; 友人を通して知る = বন্ধুর মাধ্যমে পরিচয়।":"電車で行く = أداة عادية؛ インターネットによる投票 = طريقة رسمية؛ 友人を通して知る = التعرف على شخص عبر صديق.","による-কে একটি “METHOD” লেবেল ভাবো—কাজটি কোন ব্যবস্থায় হলো তা বলে।":"فكر في による كملصق «طريقة» — يقول بأي نظام تم إنجاز المهمة.","অনলাইনের মাধ্যমে আবেদন করা যায়—によって／による ব্যবহার করে বলো।":"يمكنك التقديم عبر الإنترنت — قلها باستخدام によって／による.","কোন ব্যক্তি/বস্তু/মতামতের দিকে action, attitude বা contrast যাচ্ছে—তার target চিহ্নিত করে।":"يحدد الهدف الذي يُوجه نحوه فعل، أو موقف، أو تباين — شخص، أو شيء، أو رأي.","人に対して + আচরণ; Aに対してB + বিপরীততা; Nに対するN + noun modification। “বিরুদ্ধে” সবসময় নয়—“প্রতি”ও হতে পারে।":"人に対して + سلوك؛ Aに対してB + تباين؛ Nに対するN + تعديل اسم. ليس دائما «ضد» — يمكن أن يكون أيضا «تجاه».","～について = বিষয় সম্পর্কে; ～にとって = কার দৃষ্টিতে; ～に対して = কার/কিসের দিকে response বা বিপরীত দিক।":"～について = عن موضوع؛ ～にとって = من وجهة نظر من؛ ～に対して = رد تجاه شخص/شيء، أو اتجاه معاكس.","対-এর ছবি দুই দিক মুখোমুখি—একদিকে target, অন্যদিকে action/contrast।":"صورة 対 هي جانبان يواجهان بعضهما بعضا — على جانب الهدف، وعلى الجانب الآخر الفعل/التباين.","গ্রাহকের প্রতি ভদ্র হতে হবে—お客様に対して দিয়ে বলো।":"يجب أن تكون مهذبا مع العملاء — قلها باستخدام お客様に対して.","কারণ A থেকে ফল B হয়েছে—লিখিত, নিরপেক্ষ ও তুলনামূলকভাবে objective ভঙ্গি। ফলটি প্রায়ই অসুবিধা/ঘটনা, তবে সবসময় negative নয়।":"من السبب A، حدثت النتيجة B — نبرة مكتوبة، ومحايدة، وموضوعية نسبيا. النتيجة غالبا مشكلة أو حدث، لكنها ليست سلبية دائما.","Nのため、なAなため、plain form＋ため। বক্তার তাৎক্ষণিক ব্যক্তিগত অজুহাতে から／ので বেশি natural; notice/news-এ ため বেশি।":"Nのため、なAなため، الصيغة العادية＋ため. لعذر المتكلم الشخصي المباشر، から／ので أكثر طبيعية؛ في الإشعارات والأخبار، ため أكثر شيوعا.","～ので নরম দৈনন্দিন কারণ; ～ため formal objective cause; ～せいで খারাপ ফলের blame; ～おかげで ভালো ফলের gratitude।":"～ので سبب يومي لطيف؛ ～ため سبب رسمي موضوعي؛ ～せいで لوم على نتيجة سيئة؛ ～おかげで امتنان لنتيجة جيدة.","ট্রেনের notice কল্পনা করো: 台風のため、運休します—এটাই ため-এর formal কণ্ঠ।":"تخيل إشعار قطار: 台風のため、運休します — تلك هي الصوت الرسمي لـ ため.","তুষারের কারণে ট্রেন দেরি করেছে—ため ব্যবহার করে formal বাক্য বলো।":"تأخر القطار بسبب الثلج — قل جملة رسمية باستخدام ため.","একটি unit/ব্যক্তি/বার অনুযায়ী সংখ্যা, মূল্য বা বরাদ্দ ভাগ করে: “প্রতি…”। এখানে つき মানে “একটির সঙ্গে যুক্ত হিসেবে”।":"يقسم رقما، أو سعرا، أو تخصيصا وفقا لوحدة، أو شخص، أو مناسبة: «لكل…». هنا つき تعني «كما هو مرفق بواحد».","Nにつき＋quantity সবচেয়ে স্বাভাবিক। Notice-এর “কারণে” অর্থের Nにつき (工事中につき) আলাদা usage—context দেখবে।":"Nにつき＋كمية هي الأكثر طبيعية. أما Nにつき في الإشعارات بمعنى «بسبب» (工事中につき) فهو استخدام منفصل — تحقق من السياق.","一人につき二枚 = প্রতি ব্যক্তিতে দুইটি; 一枚ずつ = একেকটি করে distribution। 毎- prefix সময়ের নিয়মিততা দেখায়।":"一人につき二枚 = اثنتان لكل شخص؛ 一枚ずつ = واحدة لكل شخص، كتوزيع. تُظهر البادئة 毎- انتظاما في الوقت.","প্রতিটি টিকিটের সঙ্গে দুইটি coupon “attached”—attached = つき।":"قسيمتان «مرفقتان» بكل تذكرة — مرفق = つき.","একজন সর্বোচ্চ দুইটি টিকিট কিনতে পারবে—お一人につき দিয়ে বলো।":"يمكن لشخص واحد شراء تذكرتين كحد أقصى — قلها باستخدام お一人につき.","নির্দেশ, পরিকল্পনা, পূর্বাভাস বা দেখা নমুনার সঙ্গে ফল/কাজ একদম মিলেছে: “যেভাবে… ঠিক সেভাবে।”":"تطابق النتيجة/الفعل تعليمة، أو خطة، أو توقعا، أو نموذجا مرئيا تماما: «تماما كما…، هكذا بالضبط».","Vるとおり = যেভাবে হবে/বলা হয়; Vたとおり = যেভাবে হয়েছিল/বলা হয়েছিল; Nどおり-ও হয়। Particle に থাকলে adverb, の হলে noun modifier।":"Vるとおり = كما سيحدث / كما يُقال؛ Vたとおり = كما حدث / كما قيل؛ توجد أيضا Nどおり. مع الأداة に تكون ظرفا؛ ومع の تكون معدلة لاسم.","～ように “যেমন” বলতে পারে কিন্তু exact match দুর্বল; ～とおり-তে model ও result-এর correspondence স্পষ্ট। ～まま শুধু অবস্থা না বদলানো।":"يمكن لـ ～ように أيضا أن تقول «مثل»، لكن التطابق الدقيق ضعيف؛ أما ～とおり فتوضح المراسلة بين النموذج والنتيجة. أما ～まま فهي فقط عن حالة لا تتغير.","ট্রেসিং পেপারে নিচের রেখা হুবহু অনুসরণ করছ—এই exact copy-ই とおり。":"أنت تتتبع الخط الموجود أسفل ورقة شفافة، وتتبعه تماما — تلك النسخة الدقيقة هي とおり.","শিক্ষক যেভাবে বলেছেন সেভাবে লিখেছ—言われたとおりに দিয়ে বলো।":"كتبتها تماما كما قال المعلم — قلها باستخدام 言われたとおりに.","কোনো ব্যক্তি/সংস্থা/অভিজ্ঞতাকে bridge বানিয়ে অন্য মানুষ, তথ্য বা সুযোগের সঙ্গে সংযোগ হয়েছে।":"باستخدام شخص، أو منظمة، أو تجربة كجسر، يتم إنشاء اتصال مع شخص آخر، أو معلومة، أو فرصة.","মাধ্যমটি সাধারণ tool নয়; intermediary/channel-এর অনুভূতি থাকে। 人を通して, 紹介を通して, 経験を通して খুব স্বাভাবিক।":"الوسيلة ليست أداة عادية؛ لديها شعور الوسيط/القناة. 人を通して، و紹介を通して، و経験を通して طبيعية جدا.","～によって method/cause/agent; ～を通して intermediary বা entire period—এখানে “মাধ্যম” অর্থ।":"～によって هي طريقة/سبب/فاعل؛ ～を通して هي وسيط أو فترة كاملة — هنا معنى «الوسيلة».","একটি টানেলের মধ্য দিয়ে A থেকে B-তে পৌঁছাও—通して মানে সেই bridge।":"تصل إلى B من A عبر نفق — 通して هي ذلك الجسر.","বন্ধুর মাধ্যমে বর্তমান চাকরির খবর জেনেছ—友達を通して দিয়ে বলো।":"عرفت عن وظيفتك الحالية عبر صديق — قلها باستخدام 友達を通して.","একটি category বোঝাতে representative example সামনে আনে: “N-এর মতো…”। N নিজেই model; ような পরের noun-কে বর্ণনা করে।":"لإظهار فئة، يجلب مثالا تمثيليا إلى المقدمة: «مثل N…». N نفسه هو النموذج؛ ような يصف الاسم التالي.","NのようなN = N-এর মতো N; NのようにV/A = N-এর মতো করে/ভাবে। এটি exact identity নয়, similarity/example।":"NのようなN = N مثل N؛ NのようにV/A = على طريقة N / مثل N. ليس هوية دقيقة — إنه تشابه/مثال.","～みたいな কথ্য; ～のような নিরপেক্ষ/লিখিত; ～らしい সত্যিকারের বৈশিষ্ট্য; ～っぽい surface tendency।":"～みたいな عامية؛ ～のような محايدة/مكتوبة؛ ～らしい خاصية حقيقية؛ ～っぽい ميل سطحي.","একটি নমুনা কার্ড দেখিয়ে বলছ: “এইটার মতো”—Nのような।":"تُظهر بطاقة عينة وتقول «مثل هذه» — Nのような.","Tokyo-এর মতো বড় শহর—東京のような দিয়ে একটি বাক্য বানাও।":"اصنع جملة باستخدام 東京のような: «مدينة كبيرة مثل طوكيو».","তথ্যের source প্রথমে চিহ্নিত করে, তারপর সাধারণত そうだ／ということだ／らしい দিয়ে report দেয়।":"يحدد أولا مصدر المعلومة، ثم يعطي التقرير، عادة مع そうだ／ということだ／らしい.","সংবাদ, রিপোর্ট, আবহাওয়ার পূর্বাভাসের মতো source-ভিত্তিক কথায় formal। Source মানুষও হতে পারে: 先生によれば。":"هو رسمي في الكلام القائم على المصادر مثل الأخبار، والتقارير، وتوقعات الطقس. يمكن أن يكون المصدر أيضا شخصا: 先生によれば.","～によれば source; ～について topic; ～によって cause/method/agent। পরে report marker না থাকলে বাক্য অসম্পূর্ণ শোনাতে পারে।":"～によれば هو المصدر؛ ～について هو الموضوع؛ ～によって هو السبب/الطريقة/الفاعل. بدون علامة تقرير بعدها، يمكن أن تبدو الجملة غير مكتملة.","খবরের কাগজের ওপর “SOURCE:” লিখে পাশে によれば বসাও।":"اكتب «المصدر:» على صحيفة وضع によれば بجانبها.","আবহাওয়ার খবর অনুযায়ী কাল বৃষ্টি হবে—天気予報によれば দিয়ে বলো।":"وفقا لأخبار الطقس، ستمطر غدا — قلها باستخدام 天気予報によれば.","নিজে প্রত্যক্ষ না করা তথ্যকে neutral report হিসেবে অন্যকে জানায়: “জানা গেছে/শুনেছি যে…”।":"ينقل معلومات لم تشهدها بنفسك إلى الآخرين كتقرير محايد: «يُقال / سمعت أن…».","Information source আগে によれば／によると দিয়ে আসতে পারে। N/なA-তে だ বজায় থাকে: 休みだということです।":"يمكن أن يأتي مصدر المعلومة أولا مع によれば／によると. مع الأسماء وصفات な، تبقى だ: 休みだということです.","～そうです (hearsay) বেশি সংক্ষিপ্ত; ～ということです formal report; ～ということ nominalizer হলেও report meaning context-নির্ভর।":"～そうです (نقل مسموع) أقصر؛ ～ということです تقرير رسمي؛ وحتى عندما تكون ～ということ أداة اسمية، يعتمد معنى التقرير على السياق.","একজনের মুখ থেকে কথা speech-bubble হয়ে তোমার মুখে এসেছে—bubble-এর label ということです।":"كلمات من فم شخص دخلت فمك كفقاعة كلام — ملصق الفقاعة هو ということです.","স্কুল থেকে শুনেছ আগামী সপ্তাহে ছুটি—এই pattern-এ report করো।":"سمعت من المدرسة أن الأسبوع القادم عطلة — أبلغ عنها بهذا النمط.","কথা, লেখা, গবেষণা বা প্রশ্নের topic নির্ধারণ করে: “N বিষয়ে/সম্পর্কে।” Action সাধারণত জানা, বলা, ভাবা, তদন্ত করা।":"يحدد موضوع الكلام، أو الكتابة، أو البحث، أو الأسئلة: «عن/بخصوص N». الفعل عادة هو المعرفة، أو القول، أو التفكير، أو التحقيق.","NについてV; NについてのN। মানুষ target হলে শুধু “সম্পর্কে” অর্থে চলে; মানুষকে আচরণের target করতে に対して দরকার।":"NについてV؛ NについてのN. عندما يكون الشخص هدفا، يعمل فقط بمعنى «عن»؛ لجعل شخص هدفا لسلوك تحتاج إلى に対して.","～に関して আরও formal; ～に対して response/contrast; ～にとって viewpoint।":"～に関して أكثر رسمية؛ ～に対して رد/تباين؛ ～にとって وجهة نظر.","একটি ফাইলের cover-এ topic-এর নাম লিখে দাও—Nについて হলো সেই cover label।":"اكتب اسم الموضوع على غلاف ملف — Nについて هو ملصق الغلاف ذاك.","জাপানে কাজ করার নিয়ম সম্পর্কে জানতে চাই—について知りたい দিয়ে বলো।":"أريد أن أعرف عن قواعد العمل في اليابان — قلها باستخدام について知りたい.","～ている-এর casual spoken contraction। চলমান কাজ, অভ্যাস বা resulting state—মূল ている-এর অর্থই থাকে, শুধু শব্দ ছোট হয়।":"اختصار منطوق عامي لـ ～ている. فعل مستمر، أو عادة، أو حالة ناتجة — يبقى معنى ている الأصلي، فقط يصبح الصوت أقصر.","食べている→食べてる; 読んでいる→読んでる। Formal speech/লেখায় contraction না করাই নিরাপদ। ておく→とく-এর সঙ্গে গুলিও না।":"食べている→食べてる؛ 読んでいる→読んでる. في الكلام/الكتابة الرسمية من الأسلم عدم الاختصار. لا تخلط بينه وبين ておく→とく.","てる = ている; てた = ていた; てました = ていました-এর polite spoken contraction।":"てる = ている؛ てた = ていた؛ てました هي الاختصار المنطوق المهذب لـ ていました.","ている থেকে মাঝের い “চুপচাপ বাড়ি গেল”—বাকি てる।":"الـ い في وسط ている «عادت بهدوء إلى البيت» — ما يبقى هو てる.","বন্ধুকে “এখন কী করছ?” এবং উত্তর casual てる দিয়ে বলো।":"اسأل صديقا «ماذا تفعل الآن؟» وأجب، باستخدام てる العامية.","なければならない-এর casual সংক্ষিপ্ত বাধ্যতা: “করতেই হবে।” পুরো ফল না বললেও listener বুঝে নেয়—না করলে সমস্যা।":"التزام مختصر عامي من なければならない: «علي فقط أن أفعل ذلك». حتى بدون قول النتيجة الكاملة، يفهم المستمع — ستكون هناك مشكلة إذا لم تفعل.","Vない থেকে い বাদ + きゃ: 行かなきゃ。আরেক casual form なくちゃ। Teacher/manager-কে formalভাবে なければなりません ব্যবহার করো।":"من Vない، أسقط い وأضف きゃ: 行かなきゃ. صيغة عامية أخرى هي なくちゃ. لمعلم أو مدير، استخدم なければなりません رسميا.","～べき = নৈতিক/strong advice; ～なきゃ = বাস্তব necessity; ～ないと-ও casual “না হলে” থেকে obligation।":"～べき = نصيحة أخلاقية/قوية؛ ～なきゃ = ضرورة عملية؛ ～ないと أيضا التزام عامي من «إذا لم تفعل…».","লম্বা なければならない দৌড়ে ক্লান্ত হয়ে ছোট হলো—なきゃ।":"الـ なければならない الطويلة تعبت من الجري وانكمشت — なきゃ.","আজ রাতে homework শেষ করতেই হবে—casual なきゃ দিয়ে বলো।":"علي أن أنهي واجبي المنزلي الليلة — قلها بـ なきゃ العامية.","ভুলে যাওয়া তথ্য নিজের স্মৃতি থেকে টেনে নিশ্চিত করে: “কী ছিল যেন?” প্রশ্নটি listener-কেও হতে পারে, নিজেকেও।":"يسحب معلومات منسية من ذاكرتك الخاصة لتأكيدها: «ماذا كان مرة أخرى؟» يمكن أن يكون السؤال للمستمع، أو لنفسك.","আগে জানা ছিল—এখন মনে পড়ছে না। একেবারে নতুন তথ্য জিজ্ঞেস করতে ব্যবহার করো না। Past/だ form বেশি দেখা যায়: 何時だっけ、行ったっけ。":"كنت تعرفها من قبل — الآن لا يمكنك تذكرها. لا تستخدمها لطلب معلومات جديدة تماما. صيغ الماضي/だ شائعة: 何時だっけ、行ったっけ.","～かな নতুন সন্দেহ/নিজের ভাবনা; ～っけ পুরোনো memory check; ～でしょうか ভদ্র তথ্য প্রশ্ন।":"～かな شك جديد/فكرتك الخاصة؛ ～っけ فحص ذاكرة قديمة؛ ～でしょうか سؤال معلومات مهذب.","মাথার ড্রয়ার খুলে বলছ “কোথায় রেখেছিলাম…っけ?”—এটি memory-search sound।":"تفتح درجا في رأسك وتقول «أين وضعته…っけ؟» — ذلك هو صوت البحث في الذاكرة.","পরীক্ষা কয় তারিখ ছিল মনে করতে 何日だっけ দিয়ে বলো।":"قل في أي تاريخ كان الامتحان، محاولا التذكر، باستخدام 何日だっけ.","একটি সম্ভাবনা সরাসরি না বলে “হয়তো এমনও?” ভঙ্গিতে হালকা, playful বা tentative অনুমান করে।":"بدون ذكر احتمال مباشرة، يقدم تخمينا خفيفا، أو مرحا، أو تجريبيا بنبرة «ربما حتى…؟».","Intonation ও context গুরুত্বপূর্ণ। সত্যি অভিযোগ না করে teasing/soft suggestion-এ ভালো; formal situation-এ避ける।":"النبرة والسياق مهمان. إنه جيد للمزاح/الاقتراحات اللطيفة بدون شكوى حقيقية؛ تجنبه في المواقف الرسمية.","～かもしれない neutral possibility; ～たりして casual “হয়তো আবার…”; ～たり～たり একাধিক action-এর list—সম্পূর্ণ আলাদা।":"～かもしれない احتمال محايد؛ ～たりして هي «ربما حتى…» عامية؛ ～たり～たり قائمة بأفعال متعددة — مختلفة تماما.","মুখে ছোট হাসি দিয়ে “まさか、好きだったりして？”—এই playful bubble মনে রাখো।":"بابتسامة صغيرة، «まさか、好きだったりして؟» — تذكر هذه الفقاعة المرحة.","বন্ধু দেরি করেছে—“হয়তো ঘুমিয়ে পড়েছে?” たりして দিয়ে বলো।":"صديقك متأخر — «ربما نام؟» — قلها باستخدام たりして.","～ても-এর খুব casual emphatic form: বাধা A সত্য হলেও ফল B বদলাবে না—“যদিও… তবুও।”":"صيغة تأكيد عامية جدا لـ ～ても: حتى لو كانت العقبة A صحيحة، فلن تتغير النتيجة B — «حتى لو…، ما زال».","Vたって, いAくたって, N/なAだって। ঘনিষ্ঠ কথায় চলে; formal writing-এ ～ても／でも।":"Vたって، いAくたって، N/なAだって. تعمل في المحادثة القريبة؛ في الكتابة الرسمية استخدم ～ても／でも.","～ても neutral concession; ～たって casual ও জোরালো; ～からといって “শুধু এই কারণেই” ভুল সিদ্ধান্ত ঠেকায়।":"～ても تنازل محايد؛ ～たって عامية ومؤكدة؛ ～からといって تمنع استنتاجا خاطئا «لهذا السبب فقط».","て-form casual কথায় শক্ত হয়ে たって—“তবুও আমি করব!” এমন দৃঢ় কণ্ঠ।":"صيغة て تتصلب في الكلام العامي إلى たって — صوت حازم يقول «سأفعل ذلك على أي حال!».","বৃষ্টি হলেও কাজে যেতে হবে—たって দিয়ে casual বাক্য বলো।":"حتى لو أمطرت، علي أن أذهب إلى العمل — قل جملة عامية باستخدام たって.","বক্তার ব্যক্তিগত দৃঢ় বিশ্বাস: “নিশ্চয়ই এটাই/অবশ্যই হবে।” প্রমাণ দেখানো জরুরি নয়; conviction খুব শক্ত।":"اعتقاد المتكلم الشخصي الحازم: «بالتأكيد هذا هو / سيكون بالتأكيد هكذا». لا يُشترط الدليل؛ القناعة قوية جدا.","Casual/emotional judgement-এ বেশি। অন্যের বিরুদ্ধে তাড়াহুড়ো করে বললে কঠোর বা unfair শোনাতে পারে।":"هو أكثر شيوعا في الأحكام العامية/العاطفية. إذا قلته على عجل ضد شخص آخر، يمكن أن يبدو قاسيا أو غير عادل.","～はずだ যুক্তি/তথ্যভিত্তিক expectation; ～に違いない evidence-ভিত্তিক strong inference; ～に決まっている বক্তার নিশ্চিত, আবেগী conviction।":"～はずだ توقع قائم على المنطق/المعلومات؛ ～に違いない استدلال قوي قائم على الأدلة؛ ～に決まっている قناعة المتكلم الأكيدة والعاطفية.","মাথায় সিদ্ধান্তের স্ট্যাম্প: 決 = decided—“আর কোনো উত্তরই নেই।”":"ختم قرار في رأسك: 決 = تقرر — «لا توجد إجابة أخرى».","বন্ধুর বানানো খাবার নিশ্চয়ই সুস্বাদু—に決まっている দিয়ে বলো।":"الطعام الذي صنعه صديقك لذيذ بالتأكيد — قلها باستخدام に決まっている.","স্বরের ওপর অর্থ বদলায়: জানা সত্য চোখে পড়লে “দেখো, আছে তো!”, অথবা আচরণে অসন্তোষ হলে “এটা ঠিক নয়!”।":"يتغير المعنى مع النبرة: عندما تلفت حقيقة معروفة انتباهك، «انظر، إنها موجودة!»؛ أو، في عدم رضا عن سلوك، «هذا ليس صحيحا!».","Rising intonation confirmation হতে পারে; falling/strong intonation blame বা discovery। Formal প্রশ্নের ではありませんか-এর সমান সবসময় নয়।":"النبرة الصاعدة يمكن أن تكون تأكيدا؛ والنبرة الهابطة/القوية يمكن أن تكون لوما أو اكتشافا. ليس دائما مساويا للسؤال الرسمي ではありませんか.","～じゃない？ নরম confirmation-ও হতে পারে; じゃないか পুরুষালি/জোরালো; plain negative copula じゃない শুধু “নয়”।":"يمكن لـ ～じゃない؟ أيضا أن تكون تأكيدا لطيفا؛ じゃないか ذكورية/مؤكدة؛ أما الرابطة المنفية العادية じゃない فتعني فقط «ليس».","একই শব্দ, দুই মুখ: বিস্ময়ের চোখ “あるじゃない！” এবং ভ্রু কুঁচকে অভিযোগ “遅いじゃない！”।":"الكلمة نفسها، وجهان: عيون دهشة، «あるじゃない！»، وعبوس شكوى، «遅いじゃない！».","হারানো চাবি চোখের সামনে পেয়ে discovery じゃない দিয়ে বলো।":"وجدت مفتاحك المفقود أمام عينيك مباشرة — قلها بـ じゃない الاكتشاف.","Nは-এর casual topic version: “N-এর কথা বললে/যে N…”। Topic-টিকে কথোপকথনের সামনে আনে।":"النسخة العامية للموضوع من Nは: «بالحديث عن N / أما ذلك N…». تجلب الموضوع إلى مقدمة المحادثة.","Noun-এর পরে সরাসরি って। Naming/quotation-এর という অর্থও হতে পারে; পরে predicate কী করছে দেখে নির্ধারণ করো।":"تأتي って مباشرة بعد اسم. يمكن أن يكون لها أيضا معنى という للتسمية/الاقتباس؛ قرر بالنظر إلى ما يفعله المسند التالي.","田中さんって人 = という人 (নাম); 田中さんって親切だね = は (topic)। Rule 11-এর সঙ্গে form এক, function আলাদা।":"田中さんって人 = という人 (اسم)؛ 田中さんって親切だね = は (موضوع). الشكل نفسه كالقاعدة 11، وظيفة مختلفة.","って একটি spotlight—যে noun-এর পরে বসে তাকে কথার মঞ্চে তুলে ধরে।":"って هي كشاف ضوئي — ترفع الاسم الذي تتبعه إلى مسرح المحادثة.","“জাপান বলতে সত্যিই পরিষ্কার দেশ”—日本って দিয়ে casual বাক্য বলো।":"«بالحديث عن اليابان، إنها بلد نظيف حقا» — قل جملة عامية باستخدام 日本って.","দেখা লক্ষণ থেকে casual inference বা সরাসরি similarity: “মনে হচ্ছে/মতো।” বক্তার impression সামনে থাকে।":"استدلال عامي من علامات مرئية، أو تشابه مباشر: «يبدو مثل / مثل». انطباع المتكلم في المقدمة.","N/なA-তে だ লাগে না: 学生みたいだ、静かみたいだ। NみたいなN, NみたいにV/A-ও হয়।":"مع الأسماء وصفات な، لا تُضاف だ: 学生みたいだ、静かみたいだ. توجد أيضا NみたいなN وNみたいにV/A.","～ようだ neutral/formal; ～みたいだ casual; ～らしい hearsay বা typical quality; ～そうだ surface appearance।":"～ようだ محايدة/رسمية؛ ～みたいだ عامية؛ ～らしい نقل مسموع أو خاصية نموذجية؛ ～そうだ مظهر سطحي.","বন্ধুকে ছবি দেখিয়ে বলছ “猫みたい！”—casual resemblance-এর তাৎক্ষণিক শব্দ।":"تُظهر لصديق صورة وتقول «猫みたい！» — الكلمة الفورية للتشابه العامي.","আকাশ দেখে মনে হচ্ছে বৃষ্টি হবে—みたいだ দিয়ে বলো।":"بالنظر إلى السماء، يبدو أنها ستمطر — قلها باستخدام みたいだ.","অতীতে অন্য choice নিলে ভালো হতো—এখন আর বদলানো যায় না, তাই regret। ば condition + よかった positive evaluation।":"لو أنني اخترت بشكل مختلف في الماضي فقط — الآن لا يمكن تغييره، لذا هو ندم. شرط ば + تقييم إيجابي よかった.","করিনি কিন্তু করা উচিত ছিল: 行けばよかった। করেছি কিন্তু না করাই ভালো ছিল: 行かなければよかった। সময় অবশ্যই অতীতের missed chance।":"لم أفعل ذلك، لكن كان ينبغي أن أفعل: 行けばよかった. فعلت ذلك، لكن كان من الأفضل ألا أفعل: 行かなければよかった. يجب أن يكون الوقت فرصة فائتة في الماضي.","～ばいい future advice; ～ばよかった past regret; ～ばいいのに অন্যকে নিয়ে criticism/wish।":"～ばいい نصيحة مستقبلية؛ ～ばよかった ندم ماض؛ ～ばいいのに نقد/أمنية عن شخص آخر.","পেছনের রাস্তার দিকে তাকিয়ে বলছ “ও পথ নিলে ভালো হতো”—past road = ばよかった।":"النظر إلى الطريق خلفك وقول «لو أنني سلكت ذلك الطريق فقط» — طريق الماضي = ばよかった.","আগে থেকে পড়াশোনা না করার একটি অনুশোচনা এই pattern-এ বলো।":"قل ندما واحدا عن عدم الدراسة مسبقا بهذا النمط.","ばかり অন্য সবকিছুকে বাদ দিয়ে একই noun/action বেশি হচ্ছে—এই imbalance সামনে আনে। Criticism usage-এ “শুধু এটিই করে” ভাবটি মূল।":"تجلب ばかり عدم التوازن إلى المقدمة: باستثناء كل شيء آخر، يحدث الاسم/الفعل نفسه كثيرا جدا. في استخدامها للنقد، الجوهر هو شعور «إنهم يفعلون هذا فقط».","Nばかり, Vてばかりいる। বাস্তবে একেবারে ১০০% শুধু সেটিই নয়; বক্তার চোখে অস্বাভাবিক বেশি। নিজের নিরপেক্ষ routine বললে negative tone অনিচ্ছায় আসতে পারে।":"Nばかり، Vてばかりいる. في الواقع ليس حرفيا 100% ذلك فقط؛ إنه كثير بشكل غير طبيعي في عيون المتكلم. إذا استخدمتها لروتينك المحايد الخاص، يمكن أن تدخل نبرة سلبية دون قصد.","～だけ শুধু সীমা জানায়; ～ばかり criticism/একপেশে repetition দিতে পারে। ～たばかり “এইমাত্র”—সময়, এই rule নয়।":"～だけ تذكر حدا فقط؛ ～ばかり يمكن أن تعطي نقدا/تكرارا من جانب واحد. أما ～たばかり فتعني «فعلت للتو» — وقت، ليست هذه القاعدة.","একটি দাঁড়িপাল্লার সব ওজন এক পাশে—একই কাজ ばかり করায় balance নষ্ট।":"كل الوزن على جانب واحد من ميزان — فعل الفعل نفسه ばかり يدمر التوازن.","কেউ পড়াশোনা না করে শুধু মোবাইল দেখে—てばかりいる দিয়ে বলো।":"شخص لا يدرس وينظر فقط إلى هاتفه — قلها باستخدام てばかりいる.","বাস্তব জিনিস A-কে পরিচিত ছবি B-এর সঙ্গে তুলনা করে action/quality বোঝায়: “B-এর মতো করে/যেন B।”":"يقارن شيئا حقيقيا A بصورة مألوفة B لنقل فعل/جودة: «كأن B / مثل B».","Nのように + V/A; Nのような + N। এটি intentional example-ও হতে পারে, poetic metaphor-ও হতে পারে।":"Nのように + V/A؛ Nのような + N. يمكن أن يكون مثالا مقصودا، أو استعارة شعرية.","～みたいに casual; ～ように neutral/formal; ～かのように “বাস্তবে নয় কিন্তু যেন সত্যিই” আরও নাটকীয়।":"～みたいに عامية؛ ～ように محايدة/رسمية؛ ～かのように، «ليس في الواقع، لكن كأن حقا…»، أكثر درامية.","একটি transparent ছবি অন্য ছবির ওপর বসেছে—দুইটি পুরো এক নয়, কিন্তু দেখতে একইরকম।":"صورة شفافة وُضعت فوق صورة أخرى — الاثنتان ليستا واحدة تماما، لكنهما تبدوان متماثلتين.","“জাপানির মতো স্বাভাবিকভাবে কথা বলতে চাই”—ように ব্যবহার করো।":"استخدم ように: «أريد أن أتمكن من التحدث بشكل طبيعي مثل شخص ياباني».","প্রথম item-টি obvious/expected; তার সঙ্গে আরও surprising item যোগ করে: “A তো অবশ্যই, B-ও।”":"العنصر الأول واضح/متوقع؛ ويُضاف إليه عنصر أكثر إثارة للدهشة: «A، بالطبع — وB أيضا».","Aはもちろん、Bも। B সাধারণত A-এর চেয়ে কম প্রত্যাশিত বা scope-এ অতিরিক্ত। শুধু দুইটি সমান list করলে と/も যথেষ্ট।":"Aはもちろん、Bも. B عادة أقل توقعا من A، أو إضافي في النطاق. إذا كنت تسرد فقط عنصرين متساويين، فإن と/も كافية.","～ばかりでなく～も formal “শুধু নয়”; ～はもちろん～も-তে A নিয়ে সন্দেহই নেই, focus B-র extension।":"～ばかりでなく～も هي «ليس فقط» الرسمية؛ في ～はもちろん～も لا شك في A إطلاقا — التركيز هو الامتداد إلى B.","A-তে আগে থেকেই ✓ আছে; もちろん বলে B-তেও নতুন ✓ যোগ করো।":"لدى A بالفعل ✓؛ مع もちろん، أضف ✓ جديدة إلى B أيضا.","এই সাইটে grammar তো আছেই, vocabulary-ও আছে—বাক্য বানাও।":"في هذا الموقع توجد قواعد، بالطبع، ومفردات أيضا — اصنع جملة.","A-কে reference point বানিয়ে B তার সমান মাত্রায় পৌঁছায় না: “B, A-এর মতো এতটা… নয়।”":"بجعل A نقطة المرجع، لا يصل B إلى الدرجة نفسها: «B ليس … مثل A».","Aほど Bは～ない। Negative predicate comparison-এর অপরিহার্য অংশ; A “সবচেয়ে” বলা হচ্ছে না, শুধু B-এর upper benchmark।":"Aほど Bは～ない. المسند المنفي جزء أساسي من هذه المقارنة؛ لا يقول إن A هو «الأكثر» — A هو فقط المعيار الأعلى لـ B.","Rule 111-এর Aほど～はない = A-এর মতো আর কিছু নেই (superlative)। এখানে B স্পষ্ট এবং B কম।":"القاعدة 111: Aほど～はない = لا يوجد شيء مثل A (تفضيل مطلق). هنا B صريح، وB أقل.","A হলো উঁচু দাগ; B-এর রেখা সেই ほど দাগ পর্যন্ত পৌঁছাতে পারেনি।":"A علامة عالية؛ خط B لم يتمكن من الوصول إلى علامة ほど تلك.","আজ গতকালের মতো ঠান্ডা নয়—ほど…ない দিয়ে বলো।":"اليوم ليس باردا مثل أمس — قلها باستخدام ほど…ない.","একটি জিনিস/কাজের জায়গায় অন্যটি substitute হয়, অথবা একটি সুবিধার বিনিময়ে অন্য অসুবিধা balance করে।":"يُستبدل شيء/فعل بآخر، أو توازن ميزة عيبا آخر كمبادلة.","Nのかわりに, plain form＋かわりに। Person replacement, action exchange, trade-off—context দেখে reading বেছে নাও।":"Nのかわりに، الصيغة العادية＋かわりに. استبدال شخص، تبادل فعل، مفاضلة — اختر القراءة من السياق.","～にかわって official replacement-এ বেশি; ～かわりに ব্যক্তিগত substitute ও “এর বদলে/বিনিময়ে” দুটোই।":"～にかわって أكثر للاستبدال الرسمي؛ ～かわりに تغطي كلا من البدلاء الشخصيين و«بدلا من / في مقابل».","দুই পাশের দোলনা: এক পাশ উঠলে অন্য পাশ নামে—かわりに হলো exchange।":"أرجوحة بجانبين: عندما يرتفع جانب، ينخفض الآخر — かわりに هي مبادلة.","তুমি বন্ধুর shift-এর বদলে কাজ করবে—かわりに দিয়ে বলো।":"ستعمل مكان نوبة صديقك — قلها باستخدام かわりに.","একটি কাজ না করেই অন্য কাজ সম্পন্ন হয়: “A না করে B।” ない-এর বদলে compact written connector ずに।":"يُكمل فعل آخر دون فعل فعل واحد: «B دون فعل A». بدلا من ない، الرابط المكتوب المضغوط ずに.","Vない-এর ない বাদ + ずに; する→せずに বিশেষ রূপ। লিখিত/পরিপাটি, কথায় ないで বেশি common।":"أسقط ない من Vない وأضف ずに؛ する→せずに صيغة خاصة. إنه مكتوب/أنيق؛ في الكلام ないで أكثر شيوعا.","～ないで ও ～ずに প্রায় একই; ～なくて cause/state হতে পারে, কিন্তু “না করে” action sequence-এ ずに স্পষ্ট।":"～ないで و～ずに متماثلتان تقريبا؛ ～なくて يمكن أن تكون سببا/حالة، لكن في تسلسل فعل «دون فعل»، ずに واضحة.","ない মুছে ず লিখে পাশে に—একটি সরাসরি formula: 食べない→食べずに。":"امح ない، اكتب ず، وضع に بجانبها — صيغة مباشرة واحدة: 食べない→食べずに.","নাশতা না করে স্কুলে গিয়েছ—ずに দিয়ে বলো।":"ذهبت إلى المدرسة دون تناول الإفطار — قلها باستخدام ずに.","একটি অবস্থা যেমন ছিল তেমনই রেখে পরের কাজ করা বা সময় কেটে যাওয়া: state frozen, action continues।":"فعل الفعل التالي، أو مرور الوقت، مع ترك حالة كما كانت تماما: الحالة مجمدة، والفعل يستمر.","Vたまま = করে রাখা; Vないまま = না করেই সেই অবস্থা; Nのまま। Result intentional বা accidental—দুটোই হতে পারে।":"Vたまま = تُرك بعد الفعل؛ Vないまま = في حالة عدم الفعل؛ Nのまま. يمكن أن تكون النتيجة مقصودة أو عرضية — كلاهما ممكن.","～っぱなし-এ neglect/একটানা ভাব; ～まま নিরপেক্ষ unchanged state; ～ながら simultaneous action, state freeze নয়।":"لدى ～っぱなし شعور بالإهمال/الترك المستمر؛ ～まま حالة محايدة غير متغيرة؛ ～ながら فعل متزامن، ليس تجميد حالة.","ছবির PAUSE button—frame বদলায়নি, তাই まま।":"زر الإيقاف المؤقت على صورة — الإطار لم يتغير، لذا まま.","জুতা না খুলেই ঘরে ঢুকেছে—ないまま দিয়ে বলো।":"دخل شخص الغرفة دون خلع حذائه — قلها باستخدام ないまま.","লিখিত নির্দেশ, report বা formal narration-এ ます বাদ দেওয়া stem কাজগুলোকে compactভাবে জোড়া দেয়।":"في التعليمات المكتوبة، أو التقارير، أو السرد الرسمي، يربط الجذع مع إسقاط ます الأفعال بشكل مضغوط.","店を出て、駅へ向かった-এর formal লিখিত রূপ 店を出、… নয়; verb অনুযায়ী 連用形: 店を出て? সব verb শুধু stem দিয়ে যুক্ত করা natural নয়—প্রচলিত formal verbs-এ বেশি।":"الصيغة المكتوبة الرسمية لـ 店を出て、駅へ向かった ليست 店を出、…؛ تعتمد على 連用形 للفعل: 店を出て؟ لا يمكن ربط كل الأفعال بشكل طبيعي بالجذع فقط — هو أكثر شيوعا مع الأفعال الرسمية الراسخة.","て-form দৈনন্দিন ও বহুমুখী; ます-stem connection concise written style, বিশেষত recipes/notices: 加え、混ぜます।":"صيغة て يومية ومتعددة الاستخدامات؛ ربط جذع ます أسلوب مكتوب موجز، خاصة في الوصفات/الإشعارات: 加え、混ぜます.","Recipe-এর জায়গা বাঁচাতে ます কেটে comma বসেছে—切り、入れ、混ぜる。":"لتوفير المساحة في وصفة، يُقطع ます وتوضع فاصلة — 切り、入れ、混ぜる.","“কাগজটি ভাঁজ করে, বাক্সে রাখুন” recipe style stem দিয়ে লেখো।":"اكتب «اطو الورقة وضعها في الصندوق» بأسلوب الوصفات باستخدام الجذوع.","একটি চলমান মুহূর্ত/পরিস্থিতির ঠিক মধ্যে নতুন ব্যক্তি বা ঘটনা এসে ঢোকে। ところ হলো scene, へ／に হলো incoming arrow।":"في منتصف لحظة/موقف جار تماما، يأتي شخص أو حدث جديد. ところ هي المشهد؛ へ／に هي السهم القادم.","Vているところへ, Vようとしているところに। নতুন ঘটনার আগমন অনেক সময় বাধা, সাহায্য বা coincidence তৈরি করে।":"Vているところへ، Vようとしているところに. وصول حدث جديد غالبا يخلق مقاطعة، أو مساعدة، أو مصادفة.","～最中に মাঝের সর্বোচ্চ point; ～ところへ একটি scene-এ আগমন; ～たところ result discovery।":"～最中に هي نقطة المنتصف القصوى؛ ～ところへ وصول إلى مشهد؛ ～たところ اكتشاف نتيجة.","নাটকের stage-এ scene চলছে; পাশের দরজা দিয়ে নতুন চরিত্র ঢুকল—ところへ।":"مشهد يُعرض على مسرح؛ شخصية جديدة تدخل من الباب الجانبي — ところへ.","বের হতে যাচ্ছিলে, তখন বন্ধুর ফোন এলো—ところに দিয়ে বলো।":"كنت على وشك الخروج عندما جاءت مكالمة صديق — قلها باستخدام ところに.","কাজটি শুরু থেকে শেষ সীমা পর্যন্ত সম্পূর্ণ করা, অথবা ক্ষমতার শেষ পর্যন্ত করা। 切る মানে action-এর রেখা কেটে শেষ।":"إكمال فعل بالكامل من بدايته إلى حد نهايته، أو فعله إلى نهاية قدرتك. 切る تعني قطع خط الفعل عند خط النهاية.","読み切る সম্পূর্ণ পড়ে শেষ; 疲れ切る পুরোপুরি ক্লান্ত। Potential 切れる/negative 切れない-এ “পুরোটা পারা/না পারা”।":"読み切る = قراءة كاملة حتى النهاية؛ 疲れ切る = مرهق تماما. في الإمكان 切れる والنفي 切れない، تعني «يمكن/لا يمكن فعل كل ذلك».","～終わる শুধু শেষ হওয়ার fact; ～きる completion/effort-এর totality জোর দেয়। ～かけ মাঝপথে অসম্পূর্ণ।":"～終わる هي فقط حقيقة الانتهاء؛ ～きる تؤكد شمولية الإكمال/الجهد. أما ～かけ فغير مكتملة، في المنتصف.","Finish line-এ ribbon কেটে দিলে—切る = পুরো পথ শেষ।":"يُقطع الشريط عند خط النهاية — 切る = إنهاء الطريق كله.","বইটি এক দিনে সম্পূর্ণ পড়ে শেষ করেছ—読み切った দিয়ে বলো।":"قرأت الكتاب كله بالكامل في يوم واحد — قلها باستخدام 読み切った.","কোনো ব্যক্তি/ঘটনার কারণে ভালো ফল হয়েছে—কারণটির প্রতি gratitude বা positive evaluation যোগ করে।":"حدثت نتيجة جيدة بسبب شخص/حدث — تضيف امتنانا أو تقييما إيجابيا تجاه ذلك السبب.","Nのおかげで, plain form＋おかげで। Irony-তে খারাপ ফলের সঙ্গেও বলা যায়, কিন্তু tone স্পষ্ট না হলে ভুল বোঝাবে।":"Nのおかげで، الصيغة العادية＋おかげで. في السخرية يمكن قولها مع نتيجة سيئة أيضا، لكن إذا لم تكن النبرة واضحة فسيُساء فهمها.","কারণের ওপর একটি “ধন্যবাদ” sticker—সেটিই おかげ。":"ملصق «شكرا» وُضع على السبب — ذلك هو おかげ.","শিক্ষকের সাহায্যে N3 বুঝতে পেরেছ—おかげで দিয়ে বলো।":"بفضل مساعدة معلمك، تمكنت من فهم N3 — قلها باستخدام おかげで.","একটি সময়কাল শুরু থেকে শেষ পর্যন্ত বিস্তৃত: “পুরো N জুড়ে।” 通じて সময়ের tunnel-এর প্রতিটি অংশ cover করে।":"تمتد فترة زمنية من بدايتها إلى نهايتها: «طوال N كله». تغطي 通じて كل جزء من نفق الوقت.","一年を通じて／四季を通じて। সব মুহূর্তে একটানা হতে পারে, অথবা period-এর বিভিন্ন সময়ে বারবার—context নির্ধারণ করে।":"一年を通じて／四季を通じて. يمكن أن تكون مستمرة في كل لحظة، أو متكررة في أوقات مختلفة داخل الفترة — السياق يقرر.","～間ずっと strict continuous; ～を通じて entire span-এর general coverage। Rule 26 একই form-এ medium/intermediary অর্থ দেয়।":"～間ずっと استمرارية صارمة؛ ～を通じて تغطية عامة للمدى كله. تعطي القاعدة 26 الشكل نفسه معنى الوسيلة/الوسيط.","ক্যালেন্ডারের January থেকে December পর্যন্ত এক লম্বা highlight—を通じて。":"تسليط ضوء طويل واحد على التقويم من يناير إلى ديسمبر — を通じて.","জাপানে সারা বছর বৃষ্টি হয় না—一年を通じて দিয়ে একটি সত্য বাক্য বলো।":"لا تمطر طوال العام في اليابان — قل جملة حقيقية واحدة باستخدام 一年を通じて.","Negative question form হলেও এখানে invitation নয়; বক্তা নিজের মতের সঙ্গে শ্রোতার agreement চাইছে: “এমন নয় কি?”":"رغم أنها صيغة سؤال منفية، هنا ليست دعوة؛ المتكلم يطلب موافقة المستمع على رأيه الخاص: «أليس…؟»","Context ও intonation জরুরি। 行きませんか invitation হতে পারে; 便利ではありませんか evaluation confirmation।":"السياق والنبرة أساسيان. 行きませんか يمكن أن تكون دعوة؛ 便利ではありませんか تأكيد تقييم.","বাক্যের শেষে একটি ছোট “তাই না?” hook—ませんか listener-এর সম্মতি টেনে আনে।":"خطاف «أليس كذلك؟» صغير في نهاية الجملة — ませんか تجذب موافقة المستمع.","“এই পদ্ধতিটি বেশি সহজ নয় কি?”—agreement question বানাও।":"اصنع سؤال موافقة: «أليست هذه الطريقة أسهل؟»","একটি শব্দ/topic শুনলে সঙ্গে সঙ্গে যে representative image বা association মনে আসে সেটি বলে।":"عندما تسمع كلمة/موضوعا، تذكر الصورة التمثيلية أو الارتباط الذي يخطر على البال فورا.","Nというと, Nといえば। Topic define করা নয়; mental association খুলে দেওয়া। পরের কথা personal/common association হতে পারে।":"Nというと، Nといえば. ليس تعريفا للموضوع؛ إنه فتح ارتباط ذهني. ما يلي يمكن أن يكون ارتباطا شخصيا أو شائعا.","～について topic নিয়ে আলোচনা; ～というと “বললে মনে পড়ে”; ～というのは definition।":"～について مناقشة موضوع؛ ～というと هي «بالحديث عنه، أتذكر…»؛ ～というのは تعريف.","শব্দটি বলতেই মাথায় light bulb জ্বলে উঠল—Nというと → প্রথম association।":"في اللحظة التي تُقال فيها الكلمة، يضيء مصباح في رأسك — Nというと → الارتباط الأول.","“জাপান বললে ফুজি পাহাড় মনে পড়ে”—というと দিয়ে বলো।":"«بالحديث عن اليابان، يخطر جبل فوجي على البال» — قلها باستخدام というと.","নৈতিকতা, দায়িত্ব বা সাধারণ মানদণ্ড থেকে “করা উচিত/উচিত নয়” বলে শক্ত judgement দেয়।":"من الأخلاق، أو المسؤولية، أو المعايير الشائعة، يعطي حكما قويا: «يجب / لا يجب أن يفعل».","V辞書形＋べきだ; するべき／すべき দুটোই। ব্যক্তিগত ছোট পছন্দে ব্যবহার করলে অতিরিক্ত কর্তৃত্বপূর্ণ শোনাতে পারে।":"V辞書形＋べきだ؛ توجد كلتا するべき／すべき. استخدامها للتفضيلات الشخصية الصغيرة يمكن أن يبدو سلطويا بشكل مفرط.","～たほうがいい নরম personal advice; ～べきだ strong principle/duty; ～なければならない বাস্তব বাধ্যতা।":"～たほうがいい نصيحة شخصية لطيفة؛ ～べきだ مبدأ/واجب قوي؛ ～なければならない التزام عملي.","আইনের বইয়ের পাশে “SHOULD” সিল—べき。":"ختم «يجب» بجانب كتاب قانون — べき.","কর্মস্থলে সময়মতো আসা উচিত—べきだ দিয়ে বলো।":"يجب أن تصل في الوقت المحدد إلى مكان عملك — قلها باستخدام べきだ.","একই বিষয় কার viewpoint/মূল্যবোধে কেমন, তা বলে: “N-এর কাছে/দৃষ্টিতে।” N হলো evaluator, benefit receiver নয় সবসময়।":"تقول كيف يبدو الشيء نفسه من وجهة نظر/قيم من: «بالنسبة لـ N / في عيون N». N هو المقيّم، ليس دائما متلقي المنفعة.","私にとって大切だ; 学生にとって難しい। Action target নয়, judgement-এর reference person/group।":"私にとって大切だ؛ 学生にとって難しい. ليس هدف فعل — الشخص/المجموعة المرجعية للحكم.","～のために = কার জন্য কাজ; ～に対して = কার প্রতি action; ～にとって = কার দৃষ্টিতে evaluation।":"～のために = فعل شيء من أجل شخص؛ ～に対して = فعل تجاه شخص؛ ～にとって = تقييم من وجهة نظر شخص.","একই বস্তু তিনজন তিন রঙের চশমায় দেখছে—প্রতিটি চশমা にとって।":"ثلاثة أشخاص ينظرون إلى الشيء نفسه عبر ثلاث نظارات ملونة مختلفة — كل زوج من النظارات هو にとって.","তোমার কাছে পরিবার কত গুরুত্বপূর্ণ—私にとって দিয়ে বলো।":"ما مدى أهمية العائلة بالنسبة لك — قلها باستخدام 私にとって.","একটি মাত্রা বাড়া/কমার সঙ্গে আরেকটি মাত্রাও proportionalভাবে বদলায়: “যত A, তত B।”":"كلما زادت أو نقصت كمية، تتغير كمية أخرى بشكل متناسب: «كلما A أكثر، كلما B أكثر».","VばVるほど; いAければいAほど; なAならなAなほど। একই predicate পুনরাবৃত্তি formula-এর signal।":"VばVるほど؛ いAければいAほど؛ なAならなAなほど. تكرار المسند نفسه هو إشارة الصيغة.","～につれてও parallel change, কিন্তু natural progression-এ; ～ば～ほど condition-like proportional relationship।":"～につれて أيضا تغيير متواز، لكنه تقدم طبيعي؛ ～ば～ほど علاقة تناسبية تشبه الشرط.","দুইটি পাশাপাশি ওঠা সিঁড়ি—এক ধাপ A উঠলে এক ধাপ B ওঠে।":"درجان يرتفعان جنبا إلى جنب — عندما يصعد A درجة، يصعد B درجة.","যত জাপানি ব্যবহার করো, তত ভালো হও—話せば話すほど দিয়ে বলো।":"كلما استخدمت اليابانية أكثر، أصبحت أفضل — قلها باستخدام 話せば話すほど.","N-কে ঘটনার objective/formal cause হিসেবে চিহ্নিত করে: “N-এর কারণে।” News, report, data explanation-এ বেশি।":"يحدد N كسبب موضوعي/رسمي لحدث: «بسبب N». هو شائع في الأخبار، والتقارير، وشروحات البيانات.","事故による遅れ (N modification), 事故によって遅れた (sentence)। Human emotion-এর blame/gratitude নিজে যোগ করে না।":"事故による遅れ (تعديل اسم)، 事故によって遅れた (جملة). لا يضيف بنفسه لوما أو امتنانا من عاطفة إنسانية.","～せいで blame; ～おかげで benefit; ～による neutral formal cause। Rule 21 একই form-এ means/method—result noun দেখে বোঝো।":"～せいで لوم؛ ～おかげで منفعة؛ ～による سبب رسمي محايد. تعطي القاعدة 21 الشكل نفسه معنى وسيلة/طريقة — احكم من اسم النتيجة.","সংবাদপত্রের headline: 台風による被害—emotion নয়, cause label।":"عنوان صحيفة: 台風による被害 — ليست عاطفة، ملصق سبب.","ভারী বৃষ্টির কারণে ট্রেন বাতিল—による ব্যবহার করে noun phrase বানাও।":"أُلغي القطار بسبب المطر الغزير — اصنع عبارة اسمية باستخدام による.","A-তেই সীমাবদ্ধ নয়; scope B পর্যন্ত বাড়ে: “শুধু A নয়, B-ও।”":"لا يقتصر على A وحده؛ يمتد النطاق إلى B: «ليس فقط A، بل B أيضا».","Plain form/N＋ばかりでなく、Bも。লিখিত/পরিপাটি; pair-এর দুই অংশ grammaticalভাবে parallel রাখলে পরিষ্কার হয়।":"الصيغة العادية / N + ばかりでなく، B أيضا. مكتوبة ورسمية؛ تُقرأ بشكل أوضح عندما يكون جزآ الزوج متوازيين نحويا.","～だけでなく সাধারণ; ～ばかりでなく formal; ～はもちろん-এ A obvious এবং B surprising।":"～だけでなく عامة؛ ～ばかりでなく رسمية؛ مع ～はもちろん، A واضح وB هو الجزء المفاجئ.","A-র চারপাশের fence ভেঙে B-তেও জায়গা বাড়ল—ばかりでなく।":"انكسر السياج حول A وانفتح وانفتحت المساحة لتشمل B أيضا — ばかりでなく.","এই কাজ শুধু কঠিন নয়, বিপজ্জনকও—ばかりでなく দিয়ে বলো।":"قل «هذا العمل ليس صعبا فقط، بل خطير أيضا» باستخدام ばかりでなく.","A প্রতিবার ঘটলেই B নিয়মিত/স্বাভাবিকভাবে পুনরায় ঘটে। একটি event যেন B-এর repeat button।":"كلما حدث A، يحدث B بانتظام/بشكل طبيعي مرة أخرى. حدث واحد يشبه زر تكرار لـ B.","Vるたびに, Nのたびに। B প্রতিবার একই exact result না হলেও recurring reaction/habit হয়। একবারের ঘটনা নয়।":"Vるたびに، Nのたびに. لا يجب أن تكون B النتيجة نفسها تماما في كل مرة — رد فعل أو عادة متكررة تُحتسب. ليس حدثا لمرة واحدة.","～と automatic result; ～たびに repeated occasion + response; ～ごとに fixed interval/প্রতি unit।":"～と = نتيجة تلقائية؛ ～たびに = مناسبة متكررة + رد؛ ～ごとに = فترة ثابتة / لكل وحدة.","দরজার ঘণ্টা প্রতিবার চাপলেই একই আলো জ্বলে—AたびにB।":"كلما ضُغط جرس الباب، يضيء الضوء نفسه — AたびにB.","দেশের কথা মনে পড়লেই পরিবারকে ফোন দাও—たびに দিয়ে বলো।":"قل «كلما فكرت في بلدي، أتصل بعائلتي» باستخدام たびに.","জানা তথ্য, নিয়ম বা যুক্তি মিলিয়ে expected conclusion: “হওয়ার কথা/নিশ্চয়ই।” শুধু ইচ্ছা নয়; reasoning আছে।":"الجمع بين حقائق معروفة، أو قواعد، أو منطق للوصول إلى الاستنتاج المتوقع: «يجب أن يكون / لا بد أنه». ليس مجرد أمنية؛ هناك استدلال خلفه.","Plain form＋はずだ; Nのはず, なAなはず। はずだった expected ছিল কিন্তু হয়নি; はずがない logical impossibility।":"الصيغة العادية + はずだ؛ Nのはず، なAなはず. はずだった = كان متوقعا لكنه لم يحدث؛ はずがない = استحالة منطقية.","～だろう সাধারণ অনুমান; ～はず evidence-based expectation; ～に違いない আরও শক্ত inference; ～わけがない strong impossibility।":"～だろう = تخمين عام؛ ～はず = توقع قائم على الأدلة؛ ～に違いない = استدلال أقوى؛ ～わけがない = استحالة قوية.","তিনটি clue যোগ করে puzzle-এর expected answer বের হলো—সেই answer はず。":"اجمع ثلاثة أدلة وستخرج إجابة اللغز المتوقعة — تلك الإجابة هي はず.","সে সকাল ৮টায় বের হয়েছে, তাই এখন পৌঁছে যাওয়ার কথা—はずだ দিয়ে বলো।":"قل «غادر في الساعة 8 صباحا، لذا يجب أن يكون قد وصل الآن» باستخدام はずだ.","と-condition-কে です দিয়ে খুব ভদ্র customer-service style-এ আনে: “যদি এমন হয়, তাহলে…”।":"يضع شرط と داخل です ليصنع أسلوب خدمة عملاء مهذبا جدا: «إذا كان الأمر كذا وكذا، فإن…»","N/なA＋ですと; V/いA plain＋と। দোকান, ফোন, service explanation-এ natural। Casual কথায় だと／なら বেশি।":"N / なA + ですと؛ V / いA عادية + と. طبيعي في المحلات، وعلى الهاتف، وفي شروحات الخدمة. في الكلام العامي، だと / なら أكثر شيوعا.","～なら advice-এর context; ～ですと polite automatic/result condition; ～ましたら business-polite conditional।":"～なら = سياق لنصيحة؛ ～ですと = شرط مهذب تلقائي/نتيجة؛ ～ましたら = شرط مهذب للأعمال.","দোকানের কাউন্টারে condition-কে uniform পরিয়ে দিল—だと → ですと।":"عند مكتب المحل، يرتدي الشرط زيا رسميا — だと → ですと.","“এই size হলে দাম ৩,০০০ yen”—service speech-এ ですと ব্যবহার করো।":"«بهذا الحجم، السعر 3,000 ين» — قلها بكلام الخدمة باستخدام ですと.","দেখা লক্ষণ বা চলমান অবস্থা যদি সত্যিই সেই পর্যায়ে পৌঁছায়—তাহলে পরের judgement/action। よう “এমন অবস্থা”কে condition বানায়।":"إذا وصلت العلامات الملحوظة أو الحالة الجارية حقا إلى تلك المرحلة — عندها يأتي الحكم أو الفعل التالي. よう يحول «حالة كهذه» إلى شرط.","V/plain＋ようなら। Direct fact নয়; পরিস্থিতি পর্যবেক্ষণ করে conditional response। Often warning/advice: 続くようなら病院へ。":"V/عادية + ようなら. ليست حقيقة مباشرة؛ رد شرطي قائم على ملاحظة الوضع. غالبا تحذير أو نصيحة: 続くようなら病院へ。","～なら সাধারণ premise; ～ようなら “যদি লক্ষণ দেখে মনে হয় এমন চলছে/ঘটবে”। ～そうなら surface appearance-এর সরাসরি condition।":"～なら = فرضية عامة؛ ～ようなら = «إذا، بالحكم من العلامات، بدا أنه مستمر / على وشك الحدوث هكذا». ～そうなら = شرط مباشر قائم على المظهر السطحي.","Dashboard-এর warning light জ্বললে action নাও—লক্ষণ → ようなら → response।":"إذا أضاء ضوء التحذير على لوحة القيادة، اتخذ إجراء — علامة → ようなら → رد.","জ্বর চলতে থাকলে হাসপাতালে যেতে বলো—ようなら দিয়ে বলো।":"أخبر شخصا أن يذهب إلى المستشفى إذا استمرت الحمى، باستخدام ようなら.","অতীতের কোনো point থেকে পরিবর্তন/অবস্থা এগিয়ে এখন দৃশ্যমান হয়েছে। くる সময়রেখায় NOW-এর দিকে আসা arrow।":"من نقطة ما في الماضي، تقدم تغيير أو حالة وأصبح الآن مرئيا. くる هو سهم يأتي نحو الآن على الخط الزمني.","暖かくなってきた, 分かってきた, 人が増えてきた। পরিবর্তনের শুরু অতীতে, বর্তমান ফল/প্রবণতা গুরুত্বপূর্ণ।":"暖かくなってきた، 分かってきた، 人が増えてきた. بدأ التغيير في الماضي؛ النتيجة أو الاتجاه الحاضر هو المهم.","～てきた = past→now; ～ていく = now→future। Physical 来る অর্থ না ধরলেও হবে।":"～てきた = الماضي → الآن؛ ～ていく = الآن → المستقبل. لا يجب أن تأخذ 来る بمعناها المادي.","PAST ——→ NOW; arrow তোমার দিকে “এসেছে”—তাই くる।":"الماضي ——→ الآن؛ السهم «جاء» نحوك — لذلك هو くる.","জাপানি ধীরে ধীরে বুঝতে শুরু করেছ—分かってきた দিয়ে বলো।":"قل «بدأت أفهم اليابانية تدريجيا» باستخدام 分かってきた.","নিজের অসুবিধাজনক পরিস্থিতি ব্যাখ্যা করে excuse/reason নরমভাবে দেয়: “আসলে… বলে।”":"يقدم بلطف عذرا أو سببا بشرح وضعك المحرج الخاص: «الحقيقة هي…»","Plain form＋ものですから; N/なA＋なものですから। নিজের দায় এড়ানোর tone হতে পারে, তাই formal apology-তে কারণের সঙ্গে ক্ষমাও দাও।":"الصيغة العادية + ものですから؛ N / なA + なものですから. يمكن أن يبدو كأنك تتهرب من المسؤولية، لذا في اعتذار رسمي، أضف اعتذارا مع السبب.","ক্ষমা চাইতে গিয়ে কারণের চারপাশে soft cushion—ものですから।":"وسادة لطيفة حول السبب عندما تعتذر — ものですから.","ট্রেন দেরি করায় তুমি late—ものですから দিয়ে বিনয়ের সঙ্গে বোঝাও।":"أنت متأخر لأن القطار تأخر — اشرح ذلك بأدب باستخدام ものですから.","একটি বা কয়েকটি representative example casualভাবে তোলে: “যেমন N/ইত্যাদি।” কখনো topic-কে হালকা বা ছোট করে দেখায়।":"يطرح بشكل عامي مثالا تمثيليا واحدا أو بضعة أمثلة: «أشياء مثل N، وهكذا». أحيانا يجعل الموضوع يبدو خفيفا أو صغيرا.","Nなんか। Tone friendly example, surprise, disdain—সব হতে পারে; ব্যক্তি সম্পর্কে ব্যবহার করলে অসম্মান শোনাতে পারে।":"Nなんか. يمكن أن تكون النبرة مثالا وديا، أو دهشة، أو ازدراء — يمكن أن تبدو غير محترمة عند استخدامها عن شخص.","～など neutral/formal examples; ～なんか casual; Rule 90-এ একই form contempt/humility বিশেষভাবে জোরালো।":"～など = أمثلة محايدة/رسمية؛ ～なんか = عامية؛ في القاعدة 90، يحمل الشكل نفسه شعورا قويا بشكل خاص بالازدراء أو التواضع.","Formal “など” casual পোশাক পরে “なんか” হয়েছে।":"など الرسمية ترتدي ملابس عامية وتصبح なんか.","ছুটির দিনে সিনেমা ইত্যাদি দেখতে চাও—なんか দিয়ে casual বাক্য বলো।":"قل بشكل عامي، باستخدام なんか، أنك في يوم عطلتك تريد مشاهدة أفلام وأشياء من هذا القبيل.","নিজের মত/প্রস্তাবকে absolute না করে “হয়তো এমন মনে হয়” বলে নরম ও বিনয়ী করে।":"يخفف رأيك أو اقتراحك الخاص بدلا من ذكره كمطلق: «أشعر أنه ربما…» — لطيف ومتواضع.","Plain form＋かと思います। Business বা teacher-facing কথায় disagreement/estimate soft করতে উপকারী। নিজের নিশ্চিত fact-ও অযথা অস্পষ্ট করে ফেলো না।":"الصيغة العادية + かと思います. مفيدة لتخفيف الخلاف أو التقديرات في الأعمال أو عند التحدث إلى معلم. لكن لا تجعل حقائقك المؤكدة الخاصة غامضة دون داع أيضا.","～と思います সাধারণ মত; ～かと思います আরও tentative/polite; ～だろうと思います probability-এর content স্পষ্ট করে।":"～と思います = رأي عام؛ ～かと思います = أكثر ترددا/تهذيبا؛ ～だろうと思います = يجعل محتوى الاحتمال صريحا.","মতের ধারালো কোণের ওপর ছোট か cushion বসেছে—শ্রোতার কাছে নরম পৌঁছায়।":"وسادة か صغيرة تجلس على الزاوية الحادة لرأيك — تصل إلى المستمع بلطف.","“এই সময়টা সুবিধাজনক হবে বলে মনে করি”—かと思います দিয়ে বলো।":"قل «أعتقد أن هذا الوقت سيكون مناسبا» باستخدام かと思います.","A চলতে থাকাকালে সচেতন পরিকল্পনা ছাড়াই B ধীরে ধীরে পরিবর্তিত হয়। Focus হলো duration-এর ভেতরের natural change।":"بينما يستمر A، يتغير B تدريجيا دون أي خطة واعية. التركيز هو التغيير الطبيعي داخل المدة.","Vているうちに B। B accidental learning, familiarity, feeling change ইত্যাদি। Planned কাজ “সময় থাকতে করি” হলে Rule 81।":"Vているうちに B. B هو تعلم عرضي، أو ألفة متزايدة، أو تغيير في الشعور، وهكذا. للعمل المخطط — «سأفعل ذلك بينما لا يزال هناك وقت» — انظر القاعدة 81.","এই rule: 話しているうちに慣れた (চলতে চলতে বদল); Rule 81: 忘れないうちに書く (অবস্থা বদলানোর আগে করি)।":"هذه القاعدة: 話しているうちに慣れた (تغير بينما كان جاريا)؛ القاعدة 81: 忘れないうちに書く (افعله قبل أن تتغير الحالة).","একটি নদীর ভেতর চলতে চলতে পাথর মসৃণ হলো—うちに-এর natural change।":"حجر أصبح أملس أثناء جريانه داخل نهر — التغيير الطبيعي لـ うちに.","জাপানিদের সঙ্গে কথা বলতে বলতে ভয় কমেছে—うちに দিয়ে বলো।":"قل «أثناء التحدث مع أشخاص يابانيين، قل خوفي تدريجيا» باستخدام うちに.","কাজটি বক্তার অনুভূতিতে খুব অল্প আগে শেষ হয়েছে: “এইমাত্র/সবে।” ঘড়ির exact মিনিট নয়, psychological recency।":"انتهى الفعل قبل وقت قصير جدا في شعور المتكلم: «للتو / منذ لحظات فقط». ليست الدقائق الدقيقة على الساعة — حداثة نفسية.","Vたばかり। কয়েক মাসও context-এ “সবে” হতে পারে। Objective ところ-এর তুলনায় speaker judgement বেশি।":"Vたばかり. حتى بضعة أشهر يمكن أن تكون «للتو فقط» حسب السياق. بالمقارنة مع ところ الموضوعية، يلعب حكم المتكلم دورا أكبر.","Vたところ = ঠিক এখন action complete/ফল; Vたばかり = speaker মনে করে অল্প আগে; ばかり criticism নয়।":"Vたところ = الفعل انتهى للتو الآن / نتيجته؛ Vたばかり = يشعر المتكلم أنه كان قبل وقت قصير؛ هذه ばかり ليست نقدا.","ঘটনার ওপর এখনো “NEW” sticker লেগে আছে—たばかり。":"ملصق «جديد» ما زال ملتصقا بالحدث — たばかり.","তুমি জাপানে সবে এসেছ—来たばかり দিয়ে বলো।":"قل «وصلت إلى اليابان للتو فقط» باستخدام 来たばかり.","“এটা করলেই তো ভালো”—অন্যের action নিয়ে wish, complaint বা চাপযুক্ত পরামর্শ। のに unmet expectation যোগ করে।":"«لو أنك فعلت هذا فقط، لكان رائعا» — أمنية، أو شكوى، أو اقتراح ضاغط عن فعل شخص آخر. のに تضيف توقعا غير محقق.","Subject অন্য ব্যক্তি হলে criticism শোনাতে পারে। নিজের জন্যও wish হতে পারে: もっと時間があればいいのに। সম্পর্ক/টোন বিবেচনা করো।":"إذا كان الفاعل شخصا آخر، يمكن أن يبدو نقدا. يمكن أن تكون أيضا أمنية عن نفسك: もっと時間があればいいのに. ضع العلاقة والنبرة في الاعتبار.","～ばいい neutral solution; ～たほうがいい advice; ～ばいいのに emotional “করলেই তো!”।":"～ばいい = حل محايد؛ ～たほうがいい = نصيحة؛ ～ばいいのに = «لو أنك فعلت ذلك فقط!» العاطفية.","সমাধানের দরজা খোলা, কিন্তু মানুষ ঢুকছে না—তুমি বলছ “ঢুকলেই তো ভালো!”":"باب الحل مفتوح، لكن الشخص لا يدخل — أنت تقول «لو أنك دخلت فقط!».","বন্ধুকে বলো, না বুঝলে শিক্ষককে জিজ্ঞেস করলেই তো ভালো—ばいいのに।":"أخبر صديقك: إذا لم تفهم، يجب أن تسأل المعلم فقط — باستخدام ばいいのに.","শ্রোতাকে তোমার benefit-এর জন্য action করতে অনুরোধ: “আপনি কি আমার জন্য… করতে পারবেন?” もらう beneficiary viewpoint রাখে।":"طلب المستمع أن يفعل فعلا لصالحك: «هل يمكنك ربما أن تفعل… من أجلي؟» もらう تحافظ على وجهة نظر المستفيد.","Vて＋もらってもいいですか। পরিচিত/সেবা পরিস্থিতিতে polite; আরও formal হলে ～ていただけますか／いただけないでしょうか।":"Vて + もらってもいいですか. مهذبة مع أشخاص تعرفهم وفي مواقف الخدمة؛ أكثر رسمية: ～ていただけますか / いただけないでしょうか.","～てもいいですか = আমি করতে পারি?; ～てもらってもいいですか = আপনি আমার জন্য করবেন? Subject উল্টে যায়।":"～てもいいですか = هل يمكنني فعل ذلك؟؛ ～てもらってもいいですか = هل ستفعل ذلك من أجلي؟ ينقلب الفاعل.","Action giftটি আমি “পাব”—তাই もらう।":"أنا «أتلقى» هدية الفعل — لذلك هي もらう.","কাউকে একটি ছবি তুলতে অনুরোধ করো—撮ってもらってもいいですか।":"اطلب من شخص أن يلتقط صورة لك — 撮ってもらってもいいですか.","উচ্চ মর্যাদার কারও কাছ থেকে সেবা/কাজ পাওয়া humble viewpoint-এ জানায়। ご/お action-কে সম্মানিত করে, いただく নিজেকে নিচু করে।":"يُبلغ، من وجهة نظر متواضعة، عن تلقي خدمة أو عمل من شخص ذي مكانة عالية. ご/お تكرم الفعل، وいただく تخفض نفسك.","お＋和語Vます stem＋いただく; ご＋漢語N＋いただく। সব verb mechanicalভাবে নয়—প্রচলিত keigo form ব্যবহার করো।":"お + جذع ます لفعل من أصل ياباني + いただく؛ ご + اسم صيني-ياباني + いただく. لا يعمل كل فعل ميكانيكيا — استخدم صيغ كيغو الراسخة.","উপরে সম্মানিত ব্যক্তি, নিচে দুই হাতে সেবা গ্রহণ করছি—いただく-এর ছবিই “নিচ থেকে পাওয়া।”":"في الأعلى، الشخص المكرم؛ وفي الأسفل، أتلقى الخدمة بكلتا يدي — صورة いただく هي «التلقي من الأسفل».","শিক্ষক তোমার CV দেখে দিয়েছেন—ご確認いただきました দিয়ে বলো।":"قل «فحص المعلم سيرتي الذاتية لي» باستخدام ご確認いただきました.","～ていました-এর spoken polite contraction। Past continuous/habit/state একই থাকে; শুধু উচ্চারণে い বাদ।":"اختصار منطوق مهذب لـ ～ていました. الماضي المستمر، والعادة، والحالة تبقى كما هي؛ تسقط い فقط في النطق.","話していました→話してました। কথায় polite হলেও formal লিখিত text-এ পূর্ণ form ভালো। てた আরও casual।":"話していました → 話してました. حتى في الكلام هي مهذبة، لكن في الكتابة الرسمية الصيغة الكاملة أفضل. てた أكثر عامية.","てました = polite spoken; てた = casual spoken; ていました = পূর্ণ standard।":"てました = منطوقة مهذبة؛ てた = منطوقة عامية؛ ていました = صيغة قياسية كاملة.","い শব্দটি দ্রুত কথায় train miss করেছে—ていました → てました।":"كلمة い فاتها القطار في الكلام السريع — ていました → てました.","“গত রাতে দশটা পর্যন্ত কাজ করছিলাম”—てました দিয়ে spoken বাক্য বলো।":"قل بأسلوب منطوق، باستخدام てました: «كنت أعمل حتى العاشرة الليلة الماضية».","「知っている」-এর humble বিশেষ রূপ, বিশেষ করে সম্মানিত কোনো ব্যক্তিকে চিনি/জানি বলতে। নিজের জানা কাজকে নিচু করে।":"صيغة متواضعة خاصة لـ 「知っている»، خاصة لقول إنك تعرف شخصا محترما. تخفض فعل معرفتك الخاص.","Person-কে 知る: 存じ上げています। Fact/item-কে জানা: 存じています বেশি স্বাভাবিক। Negative: 存じ上げません。":"معرفة شخص بـ 知る: 存じ上げています. معرفة حقيقة أو عنصر: 存じています أكثر طبيعية. النفي: 存じ上げません.","ご存じです = “আপনি জানেন” honorific; 存じています = “আমি জানি” humble; 存じ上げる person-knowledge-এ বিশেষ।":"ご存じです = «أنت تعرف» (تكريمية)؛ 存じています = «أنا أعرف» (متواضعة)؛ 存じ上げる خاصة لمعرفة شخص.","上げる kanji দেখে ভুলে “নিজেকে ওপরে” ভাববে না—আমি সম্মানটি ওপরে তুলে দিচ্ছি, নিজে নিচে।":"لا تدع كانجي 上げる يخدعك لتفكر «أرفع نفسي» — أنا أرفع الاحترام إلى الأعلى؛ أبقى في الأسفل.","একজন সম্মানিত ব্যক্তিকে তুমি চেনো না—存じ上げません দিয়ে বলো।":"قل «لا أعرف ذلك الشخص المحترم» باستخدام 存じ上げません.","সম্মানিত ব্যক্তির চলমান action/state-কে お＋ます-stem＋です দিয়ে সংক্ষিপ্ত honorific বানায়।":"تصنع صيغة تكريمية مضغوطة لفعل أو حالة جارية لشخص محترم مع お + جذع ます + です.","先生はもうお帰りです。 সব verb নয়; single-mora stem বা unnatural combinations এড়িয়ে established form ব্যবহার করো।":"先生はもうお帰りです. لا يعمل كل فعل؛ تجنب جذوع المقطع الواحد والتركيبات غير الطبيعية، واستخدم الصيغ الراسخة.","Verb-এর সামনে お সম্মানের badge, শেষে です uniform—মাঝে ます-stem।":"お هي شارة احترام أمام الفعل، وです هي الزي في النهاية — وجذع ます في الوسط.","ম্যানেজার এখন বাইরে গেছেন/অনুপস্থিত—お出かけです দিয়ে বলো।":"قل «المدير خارج في الوقت الحالي» باستخدام お出かけです.","でしょうか সরাসরি প্রশ্নের ধার কমিয়ে অত্যন্ত ভদ্র inquiry/uncertainty বানায়।":"でしょうか تخفف حدة سؤال مباشر وتجعل استفسارا مهذبا للغاية أو تعبيرا عن عدم اليقين.","疑問語＋でしょうか, plain＋のでしょうか। দোকান, interview, email-এ উপযুক্ত। তথ্য নিশ্চিত জেনেও ব্যবহার করলে দূরত্ব তৈরি হয়।":"كلمة سؤال + でしょうか، عادية + のでしょうか. مناسبة في المحلات، والمقابلات، والبريد الإلكتروني. استخدامها حتى عندما تعرف المعلومة بالتأكيد يخلق مسافة.","ですか সাধারণ polite; でしょうか softer/more formal; ませんか invitation/agreement হতে পারে।":"ですか = مهذبة عامة؛ でしょうか = ألطف / أكثر رسمية؛ ませんか يمكن أن تكون دعوة أو طلب موافقة.","প্রশ্নচিহ্নের চারপাশে তুলোর cushion—でしょうか।":"وسادة من القطن حول علامة الاستفهام — でしょうか.","Interview-এ কাজ কখন শুরু হবে জানতে ভদ্রভাবে প্রশ্ন করো।":"في مقابلة، اسأل بأدب متى سيبدأ العمل.","です／である／いる-এর honorific equivalent; সম্মানিত ব্যক্তির identity, state বা presence উঁচু করে বলে।":"المكافئ التكريمي لـ です / である / いる؛ يتحدث عن هوية شخص محترم، أو حالته، أو وجوده بطريقة رفيعة.","N/なA＋でいらっしゃる। Person subject দরকার; নিজের বা বস্তু সম্পর্কে ব্যবহার করো না। Spoken polite: でいらっしゃいます。":"N / なA + でいらっしゃる. يجب أن يكون شخص هو الفاعل؛ لا تستخدمها عن نفسك أو الأشياء. المنطوقة المهذبة: でいらっしゃいます.","です neutral; でございます humble/polite service speech (বস্তুতেও); でいらっしゃる subject-honorific person।":"です = محايدة؛ でございます = كلام خدمة متواضع/مهذب (للأشياء أيضا)؛ でいらっしゃる = تكريمية للفاعل، لشخص.","いらっしゃる মানে সম্মানিত ব্যক্তি “উপস্থিত”—で দিয়ে তাঁর state-এ যুক্ত।":"いらっしゃる تعني أن الشخص المحترم «حاضر» — で تربطها بحالته.","অতিথি একজন বিশ্ববিদ্যালয়ের শিক্ষক—先生でいらっしゃいます দিয়ে পরিচয় দাও।":"قدم الضيف كمعلم جامعي باستخدام 先生でいらっしゃいます.","অনুমতি/পরিস্থিতির সুযোগ গ্রহণ করে বক্তা বিনয়ের সঙ্গে নিজে action করবে—humble business declaration।":"اغتناما لفرصة الإذن أو الموقف، يؤدي المتكلم الفعل بنفسه بتواضع — إعلان أعمال متواضع.","বাস্তব বা সামাজিকভাবে অনুমতি/benefit থাকার context চাই। নিজের সাধারণ কাজেও অতিরিক্ত ব্যবহার করলে “keigo overuse” শোনাতে পারে।":"يحتاج إلى سياق يوجد فيه إذن أو منفعة فعليا أو اجتماعيا. الإفراط في استخدامها لأفعالك العادية الخاصة يمكن أن يبدو «إفراطا في كيغو».","させてもらう neutral permission received; させていただく very polite/humble; いたします শুধু “করব” humble, causative permission নয়।":"させてもらう = محايدة، إذن متلقى؛ させていただく = مهذبة/متواضعة جدا؛ いたします هي فقط «سأفعل ذلك» المتواضعة — ليست إذن سببي.","দরজায় অনুমতি নিয়ে মাথা নত করে ঢুকছি—させて + いただきます।":"انحناء رأسي أثناء دخولي من الباب بإذن — させて + いただきます.","Interview শুরু করার আগে “নিজের পরিচয় দিতে দিন” এই pattern-এ বলো।":"قبل بدء المقابلة، قل «اسمحوا لي أن أقدم نفسي» بهذا النمط.","A আগে সম্পন্ন হওয়া B-এর অপরিহার্য prerequisite: “A না করা পর্যন্ত B সম্ভব/অনুমোদিত নয়।”":"يجب إكمال A أولا كشرط أساسي جوهري لـ B: «ما لم يتم A، فإن B غير ممكن / غير مسموح».","Vてからでなければ、Bない／できない। B সাধারণত negative/impossible; A শুধু chronological নয়, required gate।":"Vてからでなければ، Bない / できない. B عادة سلبية أو مستحيلة؛ A ليست مجرد ترتيب زمني — إنها بوابة مطلوبة.","～てから তারপর; ～たあとで শুধু sequence; ～てからでなければ prerequisite ছাড়া B blocked।":"～てから = بعد ذلك؛ ～たあとで = تسلسل فقط؛ ～てからでなければ = بدون الشرط المسبق، B محظورة.","A হলো locked gate-এর key; key না ঘোরালে B-room খুলবে না।":"A هي مفتاح بوابة مقفلة؛ إذا لم تدر المفتاح، فلن تفتح غرفة B.","পরিচয় যাচাই না হলে কার্ড ব্যবহার করা যাবে না—এই structure-এ বলো।":"قل «لا يمكنك استخدام البطاقة ما لم يتم التحقق من هويتك» بهذه البنية.","বাস্তবে A নয়, কিন্তু আচরণ/দৃশ্য এতটাই A-এর মতো যেন সত্যিই A—dramatic or literary simile।":"في الواقع ليس A، لكن السلوك أو المشهد يشبه A كثيرا لدرجة أنه كأن كان A حقا — تشبيه درامي أو أدبي.","Plain＋かのように; N/なA＋であるかのように। Writer জানে comparisonটি unreal/figurative।":"عادية + かのように؛ N / なA + であるかのように. يعرف الكاتب أن المقارنة غير حقيقية / مجازية.","～ように neutral resemblance; ～みたいに casual; ～かのように “যেন সত্যিই”—unreal gap ও নাটকীয়তা বেশি।":"～ように = تشابه محايد؛ ～みたいに = عامية؛ ～かのように = «كأن كان حقا» — فجوة غير حقيقية أكبر ودراما أكثر.","থিয়েটারের অভিনেতা রাজা নয়, কিন্তু এমন অভিনয় করছে যেন সত্যিই রাজা—かのように।":"ممثل مسرحي ليس ملكا، لكنه يتصرف كأنه ملك حقا — かのように.","সে সবকিছু জানে এমনভাবে কথা বলে—知っているかのように দিয়ে বলো।":"قل «يتحدث كأنه يعرف كل شيء» باستخدام 知っているかのように.","বর্তমান সুবিধাজনক অবস্থা বদলে যাওয়ার আগে সেই window-এর ভেতর intentional action শেষ করা: “সময়/সুযোগ থাকতে।”":"إنهاء فعل مقصود داخل النافذة قبل أن تتغير الحالة المواتية الحالية: «بينما لا يزال هناك وقت / فرصة».","Vる／Vない／いA／なAな／Nの＋うちに। B বক্তার পরিকল্পিত কাজ। 夜にならないうちに帰る-এর মতো deadline feeling থাকে।":"Vる / Vない / いA / なAな / Nの + うちに. B هو فعل المتكلم المخطط. هناك شعور بموعد نهائي، كما في 夜にならないうちに帰る.","Rule 68-এ A চলতে চলতে B অনিচ্ছায় বদলায়; এখানে A বদলানোর আগেই B সচেতনভাবে করি। ～間に শুধু সময়ের মধ্যে, change-before nuance কম।":"في القاعدة 68، يتغير B دون قصد بينما يستمر A؛ هنا، أفعل B عمدا قبل أن يتغير A. أما ～間に فهي فقط «داخل الوقت» — فارق «قبل أن يتغير» أضعف.","বরফ গলার আগে ice cream খেয়ে ফেলো—সুযোগের জানালা বন্ধ হওয়ার আগেই うちに।":"كل الآيس كريم قبل أن يذوب الثلج — うちに، قبل أن تنغلق نافذة الفرصة.","ভুলে যাওয়ার আগে note লিখবে—忘れないうちに দিয়ে বলো।":"قل إنك ستكتب ملاحظة قبل أن تنسى، باستخدام 忘れないうちに.","পণ্য, বই, সেবা বা তথ্য কোন নির্দিষ্ট audience-এর প্রয়োজন অনুযায়ী তৈরি—target design বোঝায়।":"منتج، أو كتاب، أو خدمة، أو معلومة صُنعت لتناسب احتياجات جمهور محدد — تشير إلى تصميم مستهدف.","N向けのN／N向けに作る। “কার উপযোগী করে বানানো” গুরুত্বপূর্ণ; কেবল destination direction নয়।":"N向けのN / N向けに作る. «صُنع ليناسب من» هو المهم؛ ليست مجرد اتجاه وجهة.","～向け = intended audience; ～向き = স্বভাবগতভাবে suitable। 子ども向けの本 বানানো হয়েছে শিশুদের জন্য; 子ども向き সহজে উপযোগী।":"～向け = جمهور مقصود؛ ～向き = مناسب بشكل طبيعي بطبيعته. 子ども向けの本 صُنع للأطفال؛ 子ども向き مناسب بسهولة للأطفال.","প্যাকেটের ওপর audience sticker: 「留学生向け」—কার দিকে design মুখ করা আছে।":"ملصق جمهور على العبوة: 「留学生向け」 — من يستهدفه التصميم.","বিদেশি শিক্ষার্থীদের জন্য তৈরি একটি guide—向け ব্যবহার করে বলো।":"قل «دليل صُنع للطلاب الدوليين» باستخدام 向け.","ব্যক্তি, দেশ, সময় বা পদ্ধতি বদলালে ফলও ভিন্ন হয়: “N ভেদে/অনুযায়ী।”":"عندما يتغير الشخص، أو البلد، أو الوقت، أو الطريقة، تختلف النتيجة أيضا: «اعتمادا على / وفقا لـ N».","Nによって違う／変わる; Nによっては exception “কিছু N-এর ক্ষেত্রে”। Cause/method/agent অর্থ context অনুযায়ী আলাদা।":"Nによって違う / 変わる؛ Nによっては = الاستثناء، «في حالة بعض N». تُميز معاني السبب/الطريقة/الفاعل بالسياق.","人によって考えが違う = ভেদে; 雨によって中止 = কারণে; インターネットによって = মাধ্যমে। Predicate অর্থটি ঠিক করে।":"人によって考えが違う = اعتمادا على (تباين)؛ 雨によって中止 = بسبب (سبب)؛ インターネットによって = بواسطة (طريقة). المسند يقرر المعنى.","একই switch বিভিন্ন মানুষ চাপলে বিভিন্ন রঙ জ্বলে—Nによって difference।":"المفتاح نفسه يضيء ألوانا مختلفة عندما يضغطه أشخاص مختلفون — اختلاف مع Nによって.","দোকানভেদে দাম আলাদা—店によって দিয়ে বলো।":"قل «تختلف الأسعار من محل إلى محل» باستخدام 店によって.","একটি কাজের একেবারে মাঝের সবচেয়ে active point-এ অন্য ঘটনা ঘটে: “ঠিক A চলার মাঝখানে।”":"في النقطة الأكثر نشاطا في منتصف فعل، يحدث حدث آخر: «في منتصف فعل A تماما».","Vている最中に／Nの最中に। ছোট interruption বা unexpected event বেশি natural। শুরু/শেষের কাছে হলে 最中 nuance দুর্বল।":"Vている最中に / Nの最中に. مقاطعة صغيرة أو حدث غير متوقع هو الأكثر طبيعية. قرب البداية أو النهاية، فارق 最中 ضعيف.","～間に broad duration; ～ところに specific phase; ～最中に peak middle এবং interruption।":"～間に = مدة واسعة؛ ～ところに = مرحلة محددة؛ ～最中に = منتصف الذروة، بالإضافة إلى مقاطعة.","Movie progress bar-এর ঠিক ৫০%-এ phone বাজল—最中。":"عند 50% تماما من شريط تقدم الفيلم، رن الهاتف — 最中.","খাওয়ার মাঝখানে manager ফোন করেছেন—最中に দিয়ে বলো।":"قل «اتصل المدير في منتصف وجبتي تماما» باستخدام 最中に.","কাজ শুরু হয়েছে কিন্তু completion-এর আগে থেমে/অসম্পূর্ণ অবস্থায় আছে: “অর্ধেক করা/করতে যাচ্ছিল।”":"بدأ العمل لكنه توقف قبل الإكمال، وتُرك في حالة غير منتهية: «نصف منجز / كان على وشك الفعل».","Vます stem＋かけ／かける／かけのN। physical অসম্পূর্ণ কাজ ও near-event দুটো: 読みかけの本, 死にかけた।":"جذع Vます + かけ / かける / かけのN. كل من العمل غير المنتهي ماديا والأحداث القريبة: 読みかけの本، 死にかけた.","～始める শুধু শুরু; ～かけ incomplete midpoint; ～きる full completion। তিনটি একটি progress bar-এর তিন জায়গা।":"～始める = البداية فقط؛ ～かけ = نقطة المنتصف غير المكتملة؛ ～きる = إكمال كامل. ثلاث نقاط على شريط تقدم واحد.","Progress bar ৪০%-এ থেমে আছে—তার ওপর かけ label।":"شريط التقدم متوقف عند 40% — مع ملصق かけ عليه.","অর্ধেক পড়া বইটি টেবিলে আছে—読みかけの本 দিয়ে বলো।":"قل «الكتاب نصف المقروء على الطاولة» باستخدام 読みかけの本.","আবেগ/স্বতঃস্ফূর্ত তাগিদ এত শক্ত যে action না করে থাকা যায় না: “নিজেকে আটকাতে পারি না।”":"عاطفة أو دافع عفوي قوي جدا لدرجة أنك لا تستطيع إلا فعل الفعل: «لا أستطيع منع نفسي».","Vない-এর ない বাদ＋ずにはいられない; する→せずにはいられない। External duty নয়, inner impulse।":"أسقط ない من Vない + ずにはいられない؛ する → せずにはいられない. ليس واجبا خارجيا — دافع داخلي.","～なければならない বাধ্যতা; ～ずにはいられない uncontrollable urge; ～てしょうがない action নয়, প্রবল feeling/state।":"～なければならない = التزام؛ ～ずにはいられない = دافع لا يمكن السيطرة عليه؛ ～てしょうがない = ليس فعلا، بل شعور/حالة شديدة.","ভেতরের spring চেপে রেখেও লাফিয়ে বের হয়—না করে থাকা যায় না।":"نابض في الداخل يدفع ويقفز حرا حتى عندما تضغطه — لا تستطيع إلا الفعل.","মজার video দেখে হাসি আটকাতে পারোনি—笑わずにはいられなかった বলো।":"قل «لم أستطع إلا الضحك على الفيديو المضحك» — 笑わずにはいられなかった.","Known reality/logic-এর ভিত্তিতে কোনো possibility সম্পূর্ণ বাতিল: “কোনোভাবেই এমন হতে পারে না।”":"استبعاد احتمال تماما بناء على واقع أو منطق معروف: «لا يمكن أن يكون ذلك صحيحا».","Plain form＋わけがない; Nの／なAな＋わけがない। Strong, তাই মানুষকে উদ্দেশ করে বললে confrontational হতে পারে।":"الصيغة العادية + わけがない؛ Nの / なAな + わけがない. إنها قوية، لذا قولها لشخص يمكن أن يبدو مواجهة.","～はずがない logical expectation negative; ～わけがない আরও categorical; ～っこない casual ability/impossibility।":"～はずがない = توقع منطقي سلبي؛ ～わけがない = أكثر قطعا؛ ～っこない = استحالة عامية للقدرة.","সম্ভাবনার দরজায় বড় X—তার ভেতরে ঢোকার “reason/わけ” নেই।":"علامة X كبيرة على باب الاحتمال — لا يوجد «سبب / わけ» للدخول.","সে প্রতিদিন পড়ে, তাই fail করার প্রশ্নই নেই—わけがない দিয়ে বলো।":"قل «يدرس كل يوم، لذا لا يمكن أن يفشل» باستخدام わけがない.","সব alternative বন্ধ; বাস্তবে বাকি একমাত্র option: “এ ছাড়া উপায় নেই।”":"كل البدائل مغلقة؛ في الواقع يبقى خيار واحد فقط: «لا يوجد خيار سوى…»","V辞書形＋しかない। বক্তা option-টি পছন্দ করতেই হবে এমন নয়; situation forced choice। Nしかない “শুধু N আছে” থেকে form আলাদা।":"صيغة قاموس V + しかない. لا يجب أن يحب المتكلم الخيار بالضرورة؛ الموقف يفرض الاختيار. يختلف الشكل عن Nしかない، «يوجد N فقط».","রাস্তার সব দরজা বন্ধ, শুধু একটি খোলা—তার ওপর しかない।":"كل باب في الشارع مغلق وباب واحد فقط مفتوح — しかない على ذلك الباب.","শেষ ট্রেন চলে গেছে, taxi নেওয়া ছাড়া উপায় নেই—しかない দিয়ে বলো।":"قل «ذهب القطار الأخير، لذا لا خيار لي سوى أخذ سيارة أجرة» باستخدام しかない.","অনেক কারণের মধ্যে ঠিক A-ই গুরুত্বপূর্ণ/মূল কারণ—positive বা meaningful result-কে জোর দেয়: “ঠিক A বলেই।”":"من بين أسباب كثيرة، يميز A كسبب مهم ورئيسي — مؤكدا نتيجة إيجابية أو ذات معنى: «تحديدا لأنه كان A».","Plain form＋からこそ। সাধারণ negative excuse-এর চেয়ে মূল্যবান insight, effort, relationship-এ বেশি natural।":"الصيغة العادية + からこそ. أكثر طبيعية للرؤى القيمة، والجهد، والعلاقات من الأعذار السلبية العادية.","～から শুধু কারণ; ～からこそ cause-এ spotlight; ～おかげで positive result-এর gratitude।":"～から = سبب فقط؛ ～からこそ = كشاف ضوئي على السبب؛ ～おかげで = امتنان لنتيجة إيجابية.","অনেক arrow-এর মধ্যে একটির ওপর spotlight—এই কারণこそ আসল।":"كشاف ضوئي على سهم واحد من بين كثير — هذا السبب こそ هو الحقيقي.","কঠোর পরিশ্রম করেছ বলেই সফল হয়েছ—からこそ দিয়ে বলো।":"قل «نجحت تحديدا لأنك عملت بجد» باستخدام からこそ.","N-কে ছোট/তুচ্ছ করে বা নিজেকে বিনয়ের সঙ্গে নিচু করে: “N-এর মতো জিনিস/আমার মতো কেউ।”":"تحقير N كشيء صغير أو تافه، أو خفض نفسك بتواضع: «شيء مثل N / شخص مثلي».","Tone বিপজ্জনক। 私なんか humble হতে পারে; あなたなんか insulting। Positive encouragement-এ নিজের self-deprecation অতিরিক্ত কোরো না।":"النبرة خطيرة. 私なんか يمكن أن تكون متواضعة؛ あなたなんか مهينة. لا تفرط في تحقير الذات في التشجيع الإيجابي أيضا.","Rule 66-এ casual example “ইত্যাদি”; এখানে contempt/humility মূল। ～など formal এবং tone তুলনামূলক neutral।":"في القاعدة 66 هي المثال العامي «أشياء مثل»؛ هنا الازدراء/التواضع هو الجوهر. أما ～など فرسمية ومحايدة نسبيا في النبرة.","N-কে হাতে ছোট করে দেখাচ্ছ—なんか। কার N ছোট করছ, সেটিই politeness ঠিক করে।":"أنت تُظهر N صغيرا في يدك — なんか. N من تصغره يقرر الأدب.","“আমার মতো মানুষ কি পারবে?”—self-humble なんか দিয়ে বলো।":"قل، مع なんか المتواضعة للذات: «هل يمكن لشخص مثلي حقا أن يفعل ذلك؟»","কথ্য ভাষায় ability/possibility জোর দিয়ে অস্বীকার: “কোনোভাবেই করতে পারবে না/হবে না।”":"في اللغة المنطوقة، نفي القدرة أو الاحتمال بشدة: «لا يمكن أن أفعل ذلك / أن يحدث ذلك».","Vます stem＋っこない। Casual, emotional; formal setting-এ わけがない／できるはずがない বেশি উপযুক্ত।":"جذع Vます + っこない. عامية وعاطفية؛ في المواقف الرسمية わけがない / できるはずがない أكثر مناسبة.","～わけがない general logical impossibility; ～っこない colloquial “অসম্ভব!” এবং action verb-এর stem।":"～わけがない = استحالة منطقية عامة؛ ～っこない = «مستحيل!» عامية وتأخذ جذع فعل.","ছোট っ দেয় শক্ত ধাক্কা—できっこない! মুখের জোর মনে রাখো।":"الـ っ الصغيرة تعطي دفعة قوية — できっこない! تذكر قوة الكلمة المنطوقة.","এত কাজ এক ঘণ্টায় শেষ করা অসম্ভব—終わりっこない দিয়ে বলো।":"قل «من المستحيل إنهاء هذا القدر من العمل في ساعة واحدة» باستخدام 終わりっこない.","A কারণটি সত্য হলেও শুধু সেটি থেকে extreme/simple conclusion B টানা যায় না: “A বলেই B—এমন নয়।”":"حتى لو كان السبب A صحيحا، لا يمكنك استخلاص الاستنتاج المتطرف أو البسيط B منه وحده: «فقط لأن A، لا يعني B».","Aからといって、必ずしもBとは限らない／Bわけではない প্রায়ই জোড়া হয়। Stereotype/overgeneralization ঠেকায়।":"غالبا تُقرن Aからといって مع 必ずしもBとは限らない / Bわけではない. تمنع الصور النمطية والتعميم المفرط.","～ても বাধা সত্ত্বেও result; ～からといって cause থেকে ভুল conclusion অস্বীকার; ～とは限らない universality অস্বীকার।":"～ても = نتيجة رغم عقبة؛ ～からといって = رفض استنتاج خاطئ مستخلص من سبب؛ ～とは限らない = نفي الشمولية.","A থেকে B-তে arrow টেনেছিলে; মাঝখানে STOP sign—কারণ আছে, কিন্তু conclusion automatic নয়।":"رسمت سهما من A إلى B؛ في الوسط توجد علامة STOP — يوجد سبب، لكن الاستنتاج ليس تلقائيا.","জাপানে থাকলেই জাপানি ভালো হয় না—からといって দিয়ে বলো।":"قل «مجرد العيش في اليابان لا يعني أن يابانيتك ستتحسن» باستخدام からといって.","একটি statement অনেক ক্ষেত্রে সত্য হলেও সবসময়/সব মানুষের জন্য ১০০% নয়: “অবশ্যই এমন নয়।”":"عبارة قد تكون صحيحة في حالات كثيرة، لكن ليس دائما، وليس 100% للجميع: «ليس بالضرورة هكذا».","Plain form＋とは限らない। Exceptions-এর দরজা খোলা রাখে; claim পুরো false বলছে না।":"الصيغة العادية + とは限らない. تترك الباب مفتوحا للاستثناءات؛ لا تقول إن الادعاء خاطئ تماما.","～わけではない statement আংশিক negate/explain; ～とは限らない universal certainty negate; ～かもしれない individual possibility।":"～わけではない = تنفي جزئيا / تشرح عبارة؛ ～とは限らない = تنفي اليقين الشامل؛ ～かもしれない = احتمال فردي.","১০০% লেখা circle-এর এক ছোট অংশ মুছে দাও—limit universal নয়।":"امح جزءا صغيرا من الدائرة المسماة 100% — الشامل له حد.","দামি জিনিস সবসময় ভালো নয়—とは限らない দিয়ে বলো।":"قل «الأشياء الغالية ليست جيدة دائما» باستخدام とは限らない.","কোনো অভিজ্ঞতার মাত্রা এত প্রবল যে বক্তা আবেগে বলে “N কী যে…!”—surprise, praise বা complaint।":"درجة تجربة ما شديدة جدا لدرجة أن المتكلم يهتف عاطفيا، «يا له من N…!» — دهشة، أو مدح، أو شكوى.","N（のこと）といったら। পরের clause-এ degree/evaluation আসে। Neutral topic introduction নয়; emotional exclamation।":"N（のこと）といったら. تأتي درجة أو تقييم في العبارة التالية. ليست مقدمة موضوع محايدة؛ هتاف عاطفي.","～というと association; ～といったら emotional degree; ～ほど degree-এর grammatical measure।":"～というと = ارتباط؛ ～といったら = درجة عاطفية؛ ～ほど = مقياس الدرجة النحوي.","কথা বলতে গিয়ে হাত ছড়িয়ে “কী যে ছিল!”—এই dramatic gesture = といったら。":"بسط يديك أثناء الكلام — «كيف كان!» — تلك الإيماءة الدرامية = といったら.","গতকালের ব্যস্ততা কী যে ছিল—忙しさといったら দিয়ে বলো।":"قل «لا يمكنك تخيل مدى انشغال أمس» باستخدام 忙しさといったら.","A সত্য হওয়া সত্ত্বেও B আচরণ expectation-এর বিপরীত—এ নিয়ে রাগ, তিরস্কার বা contempt।":"رغم أن A صحيح، فإن السلوك B يخالف التوقع — غضب، أو لوم، أو ازدراء حيال ذلك.","Plain＋くせに; Nの／なAな＋くせに। Subject সাধারণত একই/সংশ্লিষ্ট। নিজের ওপর self-criticism ছাড়া polite conversation-এ সতর্ক।":"عادية + くせに؛ Nの / なAな + くせに. الفاعل عادة نفسه أو مرتبط. في المحادثة المهذبة، كن حذرا إلا لنقد الذات عن نفسك.","“জানে, তবু…” বলে ভ্রু কুঁচকে থাকা মুখ—くせに-এর tone।":"وجه بجبين مجعد يقول «كنت تعرف، ومع ذلك…» — تلك هي نبرة くせに.","জানার পরও সে বলেনি—知っていたくせに দিয়ে বলো।":"قل «رغم أنه كان يعرف، لم يخبرني» باستخدام 知っていたくせに.","কোনো গুণ surface-এ বেশি দেখা যায়, বা বারবার সেই tendency আছে: “-সুলভ/-ঘেঁষা/প্রবণ।”":"تظهر جودة بقوة على السطح، أو يظهر ذلك الميل مرارا: «-يشبه / -مثل / عرضة لـ».","N＋っぽい, Vます stem＋っぽい, いA stem＋っぽい। Negative tendency common: 忘れっぽい, 油っぽい; তবে 大人っぽい neutral/positive হতে পারে।":"N + っぽい، جذع Vます + っぽい، جذع いA + っぽい. الميول السلبية شائعة: 忘れっぽい، 油っぽい؛ لكن 大人っぽい يمكن أن تكون محايدة أو إيجابية.","～らしい true/expected characteristic; ～っぽい appearance/tendency, প্রায়ই imperfect; ～みたい direct resemblance।":"～らしい = خاصية حقيقية/متوقعة؛ ～っぽい = مظهر/ميل، غالبا غير كامل؛ ～みたい = تشابه مباشر.","আসল রং নয়, ওপরের দিকে সেই রঙের tint—っぽい।":"ليس اللون الحقيقي — مسحة من ذلك اللون على السطح — っぽい.","তুমি সম্প্রতি একটু ভুলোমনা হয়ে গেছ—忘れっぽい দিয়ে বলো।":"قل «أصبحت تنسى قليلا مؤخرا» باستخدام 忘れっぽい.","A-কে খারাপ ফল B-এর দায়ী কারণ হিসেবে দেখায়: “A-এর দোষে।” Speaker blame/negative evaluation বহন করে।":"تقدم A كسبب يُلام على النتيجة السيئة B: «إنه خطأ A». يحمل المتكلم لوما وتقييما سلبيا.","Plain/Nの＋せいで; uncertainty হলে せいか “হয়তো A-এর জন্য।” Neutral science/report-এ による বেশি।":"عادية / Nの + せいで؛ إذا غير مؤكد، せいか = «ربما بسبب A». في العلوم أو التقارير المحايدة، による أكثر شيوعا.","～おかげで ভালো ফল; ～せいで খারাপ ফল; ～ため neutral/formal cause।":"～おかげで = نتيجة جيدة؛ ～せいで = نتيجة سيئة؛ ～ため = سبب محايد/رسمي.","কারণের গায়ে কালো “দোষ” sticker—せい。":"ملصق «خطأ» أسود ملتصق بالسبب — せい.","ঘুম কম হওয়ার কারণে কাজে ভুল হয়েছে—せいで দিয়ে বলো।":"قل «ارتكبت خطأ في العمل لأنني لم أنم بما يكفي» باستخدام せいで.","কোনো পরিচিত ব্যক্তির স্বভাব/ইতিহাস জানি বলেই তার ভবিষ্যৎ আচরণ সম্পর্কে prediction করি: “সে তো এমন মানুষ, তাই নিশ্চয়…”।":"لأنني أعرف شخصية شخص مألوف وتاريخه، أتنبأ بسلوكه المستقبلي: «هذا هو نوع الشخص الذي هم عليه، لذا بالتأكيد…»","Nのことだから। N সাধারণত speaker/listener-এর পরিচিত ব্যক্তি/group। Unknown object-এর objective cause নয়।":"Nのことだから. N عادة شخص أو مجموعة مألوفة للمتكلم والمستمع. ليس سببا موضوعيا يتضمن شيئا غير معروف.","～から সাধারণ cause; ～のことだから character-based inference; ～に違いない conclusion-এর certainty, personality premise নয়।":"～から = سبب عام؛ ～のことだから = استدلال قائم على الشخصية؛ ～に違いない = يقين الاستنتاج، ليس فرضية شخصية.","ব্যক্তির profile card দেখে পরের action অনুমান—“ওর কথা যখন…” = のことだから।":"بالنظر إلى بطاقة ملف الشخص، تخمن فعله التالي — «معرفتهم…» = のことだから.","সময়ের ব্যাপারে খুব সতর্ক বন্ধুটি নিশ্চয় দেরি করবে না—のことだから দিয়ে বলো।":"قل «صديقي حريص جدا على الوقت، لذا بالتأكيد لن يتأخر» باستخدام のことだから.","সম্পূর্ণ অবস্থা নয়—সামান্য সেই দিকে ঝোঁক/লক্ষণ: “একটু… ভাব/প্রবণতা।” প্রায়ই শরীর বা negative condition।":"ليست الحالة الكاملة — مجرد ميل طفيف أو علامة في ذلك الاتجاه: «ميل قليل إلى…». غالبا الجسم أو حالة سلبية.","N＋気味, Vます stem＋気味। 疲れ気味・遅れ気味। Temporary mild tendency; personality-এর দীর্ঘ habit-এ っぽい হতে পারে।":"N + 気味، جذع Vます + 気味. 疲れ気味・遅れ気味. ميل مؤقت خفيف؛ لعادة شخصية طويلة الأمد، قد تناسب っぽい بشكل أفضل.","～気味 mild/current sign; ～っぽい habitual/appearance; ～がち frequent negative tendency (এই page-এ না থাকলেও পার্থক্য মনে রাখো)।":"～気味 = علامة خفيفة/حالية؛ ～っぽい = عادية/مظهر؛ ～がち = ميل سلبي متكرر (تذكر الفرق رغم أنه ليس في هذه الصفحة).","Dashboard needle danger zone-এ পুরো ঢোকেনি, একটু হেলে আছে—気味।":"إبرة لوحة القيادة لم تدخل منطقة الخطر بالكامل — إنها مائلة قليلا فقط — 気味.","আজকাল একটু ঘুম কম হচ্ছে/ক্লান্ত লাগছে—気味 দিয়ে বলো।":"قل «مؤخرا أنام أقل قليلا / أشعر بالتعب» باستخدام 気味.","যে noun/action-কে reject করা হচ্ছে সেটিকে contempt/emotion সহ সামনে এনে শক্ত否定: “ওরকম N একদমই নয়/করব না।”":"جلب الاسم أو الفعل المرفوض إلى المقدمة بازدراء وعاطفة لنفي قوي: «ذلك النوع من N — إطلاقا لا / لن أفعل ذلك».","Nなんか＋negative। Tone খুব শক্ত; জিনিস/নিজের idea-তে চলতে পারে, ব্যক্তির দিকে বললে অপমানজনক।":"Nなんか + نفي. النبرة قوية جدا؛ تعمل للأشياء وأفكارك الخاصة، لكن قولها تجاه شخص مهين.","～なんか example বা humility হতে পারে; なんか…ない-এ negative predicate সঙ্গে strong rejection নিশ্চিত।":"يمكن أن تكون ～なんか مثالا أو تواضعا؛ مع なんか…ない بالإضافة إلى مسند منفي، الرفض القوي مؤكد.","N-কে হাত দিয়ে দূরে ঠেলে বলছ “না, একদম না!”—なんか…ない।":"دفع N بعيدا بيدك وقول «لا، إطلاقا لا!» — なんか…ない.","“আমি মিথ্যা বলব না”—strong うそなんかつかない দিয়ে বলো।":"قل «لن أكذب أبدا» مع うそなんかつかない القوية.","সবচেয়ে extreme/minimum example-টিও সত্য বা মিথ্যা—সেখান থেকে অন্যগুলো আরও obvious: “এমনকি…ও।”":"حتى المثال الأكثر تطرفا أو الأدنى صحيح أو خاطئ — ومن هناك، البقية أكثر وضوحا: «حتى…»","Nさえ, particle＋さえ: 私にさえ。Context positive/negative দুটোই। Minimum condition-এর ～さえ～ば আলাদা extension।":"Nさえ، أداة + さえ: 私にさえ. يمكن أن يكون السياق إيجابيا أو سلبيا. أما الحد الأدنى للشرط ～さえ～ば فهو امتداد منفصل.","～も সাধারণ “ও”; ～さえ surprising extreme; ～まで unexpected endpoint/person পর্যন্ত।":"～も = «أيضا» عامة؛ ～さえ = متطرف مفاجئ؛ ～まで = حتى نقطة نهاية أو شخص غير متوقع.","সিঁড়ির একেবারে শেষ/অবিশ্বাস্য ধাপেও ✓—সেই extreme さえ।":"علامة ✓ حتى على الدرجة الأخيرة غير القابلة للتصديق من الدرج — ذلك المتطرف さえ.","এত ব্যস্ত যে দুপুরের খাবারের সময়ও নেই—時間さえない বলো।":"قل «أنا مشغول جدا لدرجة أنني لا أملك حتى وقتا للغداء» — 時間さえない.","একটি example/result দিয়ে degree বোঝায়: “এতটা… যে/অন্তত এতটুকু।” কথ্য ভাষায় ぐらい খুব common।":"إظهار الدرجة بمثال أو نتيجة واحدة: «لدرجة أن… / على الأقل هذا القدر». في اللغة المنطوقة، ぐらい شائعة جدا.","Plain/N＋くらい／ぐらい। Extreme degree, minimum suggestion, approximation—context অনুযায়ী।":"عادية / N + くらい / ぐらい. درجة متطرفة، اقتراح أدنى، تقريب — حسب السياق.","～ほど degree তুলনায় একটু objective/strong scale; ～くらい কথ্য এবং “এই পরিমাণ”। くらいなら choice comparison-ও আলাদা।":"～ほど مقياس درجة أكثر موضوعية/قوة بقليل من ～くらい، التي هي منطوقة وتعني «هذا القدر». أما くらいなら، لمقارنة الاختيار، فهي منفصلة أيضا.","হাতে একটি মাপ দেখিয়ে “এইটুকু/এতটা”—ぐらい।":"إظهار قياس بيدك — «هذا القدر / ذلك القدر» — ぐらい.","এত ক্লান্ত যে নড়তে পারছ না—動けないくらい দিয়ে বলো।":"قل «أنا متعب جدا لدرجة أنني لا أستطيع التحرك» باستخدام 動けないくらい.","কাজ করে resulting state ঠিক না করে ফেলে রাখা, অথবা action একটানা চলতে থাকা: “যেমন আছে তেমন ছেড়ে/অবিরত।”":"ترك الحالة الناتجة كما هي بعد فعل شيء، دون تصحيحها، أو فعل يستمر دون توقف: «تُرك كما هو / طوال الوقت».","Vます stem＋っぱなし। 開けっぱなし neglect; 立ちっぱなし continuous. প্রায়ই negative burden/criticism।":"جذع Vます + っぱなし. 開けっぱなし = إهمال؛ 立ちっぱなし = مستمر. غالبا عبء سلبي أو نقد.","～まま neutral unchanged state; ～っぱなし negligence বা long continuous effort জোর দেয়।":"～まま = حالة محايدة غير متغيرة؛ ～っぱなし تؤكد الإهمال أو جهدا مستمرا طويلا.","দরজা খুলে চলে গেছ—OPEN light সারাক্ষণ জ্বলছে: 開けっぱなし。":"فتحت الباب ومشيت بعيدا — ضوء OPEN يبقى مضاء طوال الوقت: 開けっぱなし.","সারাদিন দাঁড়িয়ে কাজ করেছ—立ちっぱなし দিয়ে বলো।":"قل «عملت واقفا طوال اليوم» باستخدام 立ちっぱなし.","একটি অনাকাঙ্ক্ষিত জিনিস অসংখ্য/সর্বত্র ছড়িয়ে “ভরা”: Nだらけ।":"شيء غير مرغوب انتشر مرات لا تحصى أو في كل مكان — «مليء بـ»: Nだらけ.","泥だらけ・間違いだらけ・傷だらけ। সাধারণত negative/dirty/error; flowers দিয়ে neutral beauty বলতে いっぱい বেশি natural।":"泥だらけ・間違いだらけ・傷だらけ. عادة سلبية، أو متسخة، أو أخطاء؛ للحديث عن جمال محايد مع الزهور، いっぱい أكثر طبيعية.","～まみれ-ও পুরো লেপা (বিশেষত liquid/dirt); ～だらけ countable/spread undesirable things-এর broad coverage।":"～まみれ أيضا «ملطخ في كل مكان» (خاصة سائل أو أوساخ)؛ ～だらけ تغطية واسعة بأشياء غير مرغوبة قابلة للعد أو منتشرة.","সাদা জামার সব জায়গায় কাদার দাগ—泥だらけ।":"بقع طين في كل مكان على قميص أبيض — 泥だらけ.","লেখাটি ভুলে ভরা—間違いだらけ দিয়ে বলো।":"قل «الكتابة مليئة بالأخطاء» باستخدام 間違いだらけ.","কারও action/possibility সরাসরি assert না করে একটি possible example হিসেবে তুলে expression নরম করে।":"تخفيف تعبير بتقديم فعل شخص أو احتماله ليس كتأكيد مباشر بل كمثال محتمل واحد.","Vたりして。Teasing, self-conscious confession, soft speculation। Rule 34 প্রশ্নস্বরের playful guess; এখানে statement-এ soft mention।":"Vたりして. مزاح، اعتراف واع بالذات، تكهن لطيف. القاعدة 34 تخمين مرح بنبرة استفهامية؛ هنا ذكر لطيف في عبارة.","～たり～たり multiple examples list; single ～たりして “এমনও করে/হয়তো এমন” softener।":"～たり～たり تسرد أمثلة متعددة؛ أما ～たりして واحدة فهي المخفف «يفعل أشياء مثل… / ربما…».","কঠিন statement-কে bubble wrap দিয়ে জড়িয়ে বলছ—たりして।":"تغليف عبارة صلبة بغلاف فقاعي قبل قولها — たりして.","ছুটির দিনে মাঝে মাঝে একাই সিনেমা দেখতে যাও—softly たりします বলো।":"قل بلطف، باستخدام たりします، أنك في أيام العطلة تذهب أحيانا إلى السينما وحيدا.","N-এর সত্যিকারের expected বৈশিষ্ট্য যথাযথভাবে দেখা যায়: “N-সুলভ/একেবারে N-এর মতো হওয়া উচিত যেমন।”":"تظهر خاصية N الحقيقية والمتوقعة تماما كما ينبغي: «نموذجي لـ N / تماما كما يجب أن يكون N».","Nらしい／NらしいN। Person role, season, style: 春らしい日。Hearsay らしい-এর form একই, কিন্তু plain clause + source context-এ “শুনেছি”।":"Nらしい / NらしいN. دور شخص، أو موسم، أو أسلوب: 春らしい日. أما النقل المسموع らしい فلها الشكل نفسه، لكن مع عبارة عادية وسياق مصدر تعني «سمعت أن…»","男らしい = culturally typical/manly; 男っぽい = surface masculine-ish; 男みたい = দেখতে/আচরণে লোকটির মতো।":"男らしい = نموذجي ثقافيا / رجولي؛ 男っぽい = يشبه الذكور سطحيا؛ 男みたい = مثل ذلك الرجل في المظهر أو السلوك.","Category checklist-এর সব box tick—তাই “সত্যিকারের Nらしい।”":"كل مربع في قائمة فحص الفئة مُعلّم — لذا هو «Nらしい حقيقي».","আজ বসন্তের মতো উষ্ণ দিন—春らしい দিয়ে বলো।":"قل «اليوم يوم دافئ يشبه الربيع» باستخدام 春らしい.","এক মুহূর্তে A মনে হয়েছিল, কিন্তু পরে বাস্তবতা আলাদা হলো—mistaken expectation/near misinterpretation।":"للحظة بدا أنه A، لكن لاحقا تبين أن الواقع مختلف — توقع خاطئ / تفسير خاطئ قريب.","Plain＋かと思った。পরের clause-এ ら／が দিয়ে correction/contrast আসা natural। Literal “ভাবলাম কি না” নয়।":"عادية + かと思った. من الطبيعي أن يتبع تصحيح أو تباين مع ら / が. ليست حرفيا «تساءلت عما إذا…»","～と思った শুধু past thought; ～かと思った “আমি তো ভেবেছিলাম/মনে হলো”—প্রায়ই surprise correction।":"～と思った = مجرد فكرة ماضية؛ ～かと思った = «اعتقدت أنه كان… / بدا…» — غالبا تصحيح مفاجئ.","চোখে প্রথমে এক ছবি, blink করার পর অন্য ছবি—প্রথম frame かと思った।":"أولا صورة واحدة أمام عينيك، وبعد غمضة، صورة أخرى — الإطار الأول هو かと思った.","ট্রেন এসেছে ভেবেছিলে, কিন্তু express চলে গেছে—かと思ったら দিয়ে বলো।":"قل «اعتقدت أن القطار قد جاء، لكن القطار السريع مر» باستخدام かと思ったら.","পুরো list না দিয়ে কয়েকটি representative example casualভাবে পাশাপাশি রাখে: “যেমন A, B ইত্যাদি।”":"دون إعطاء القائمة الكاملة، وضع بضعة أمثلة تمثيلية بشكل عامي جنبا إلى جنب: «أشياء مثل A، وB، وهكذا».","NとかNとか; V辞書＋とか। List অসম্পূর্ণ—আরও items আছে বোঝায়। Formal লেখায় ～や～など।":"NとかNとか؛ صيغة قاموس V + とか. القائمة غير مكتملة — تشير إلى وجود عناصر أكثر. في الكتابة الرسمية، ～や～など.","～たり～たり actions/examples এবং conjugation লাগে; ～とか～とか nouns/quoted options-এ casual; ～と সম্পূর্ণ list-এর অনুভূতি।":"～たり～たり تغطي أفعالا/أمثلة وتحتاج إلى تصريف؛ ～とか～とか عامية للأسماء والخيارات المقتبسة؛ ～と تعطي شعور قائمة كاملة.","Shopping list-এর শেষে “…” আছে—AとかBとか…。":"توجد «…» في نهاية قائمة التسوق — AとかBとか….","ছুটিতে রান্না বা সিনেমা দেখা ইত্যাদি করো—とか～とか দিয়ে বলো।":"قل «في أيام عطلتي أفعل أشياء مثل الطبخ ومشاهدة الأفلام» باستخدام とか～とか.","প্রধান কাজ A করতে যাওয়ার/করার সুযোগে অতিরিক্ত ছোট কাজ B করা: “যেতে যেতেই/সুযোগে।”":"فعل مهمة صغيرة إضافية B بمناسبة الذهاب لفعل / فعل المهمة الرئيسية A: «بينما أنا عند ذلك / في الطريق».","Vる／Vた／Nの＋ついでに। A অবশ্যই মূল উদ্দেশ্য, B secondary ও সুবিধাজনক। শুধু একসঙ্গে দুই সমান কাজ নয়।":"Vる / Vた / Nの + ついでに. A بالتأكيد هو الغرض الرئيسي؛ B ثانوي ومريح. ليست مجرد مهمتين متساويتين تُفعلان معا.","Main shopping bag-এর পাশে free ছোট bag—অতিরিক্ত কাজ B হলো ついで।":"بجانب حقيبة التسوق الرئيسية، حقيبة صغيرة مجانية — المهمة الإضافية B هي ついで.","স্টেশনে যাওয়ার পথে convenience store-এ ঢুকবে—ついでに দিয়ে বলো।":"قل «سأتوقف عند متجر البقالة في طريقي إلى المحطة» باستخدام ついでに.","দেখা evidence/পরিস্থিতি থেকে বক্তা খুব শক্ত inference করে: “নিশ্চয়ই/নিঃসন্দেহে।”":"من الأدلة والوضع المرئي، يقدم المتكلم استدلالا قويا جدا: «بالتأكيد / دون شك».","Plain＋に違いない; N/なA-তে だ সাধারণত বাদ। Objective proof নয়, speaker certainty; formal/written-এ বেশি দেখা যায়।":"عادية + に違いない؛ مع N / なA، تسقط だ عادة. ليس دليلا موضوعيا — يقين المتكلم؛ يُرى أكثر في اللغة الرسمية والمكتوبة.","দুইটি clue মিলিয়ে detective বলছে “এটাই culprit—違いない!”":"بجمع دليلين معا، يقول المحقق «ذلك هو الجاني — 違いない!»","আলো জ্বলছে, তাই কেউ নিশ্চয় ঘরে আছে—に違いない দিয়ে বলো।":"قل «الضوء مضاء، لذا لا بد أن شخصا ما في الغرفة» باستخدام に違いない.","একটি category-তে A-কে সর্বোচ্চ benchmark বানায়: “A-এর মতো এত… আর কিছু/কেউ নেই।” Negative form দিয়ে superlative।":"جعل A أعلى معيار في فئة: «لا شيء / لا أحد … مثل A». تفضيل مطلق باستخدام الصيغة المنفية.","Aほど adjective Nはない／いない。 Speaker evaluation; absolute scientific ranking নাও হতে পারে।":"Aほど صفة Nはない / いない. تقييم المتكلم؛ قد لا يكون ترتيبا علميا مطلقا.","Rule 44: BはAほど～ない = B কম; এখানে Aほど～はない = A-ই সবচেয়ে। B আছে কি না দেখে পার্থক্য ধরো।":"القاعدة 44: BはAほど～ない = B أقل؛ هنا Aほど～はない = A هو الأكثر. اكتشف الفرق بالتحقق مما إذا كان B موجودا.","Podium-এর ১ নম্বরে A; পাশে কেউ A-এর ほど উচ্চতায় নেই।":"A في الرقم 1 على المنصة؛ بجانبه، لا أحد يصل إلى ارتفاع ほど لـ A.","স্বাস্থ্যের মতো গুরুত্বপূর্ণ কিছু নেই—ほど…ない দিয়ে বলো।":"قل «لا يوجد شيء مهم مثل الصحة» باستخدام ほど…ない.","N-কে পুরোপুরি বাদ দিয়ে কাজ/আলোচনা করা: “N ছাড়া/বাদ দিয়ে।” 抜く মানে টেনে বের করা।":"فعل عمل أو إجراء مناقشة مع ترك N خارجا تماما: «بدون / باستثناء N». 抜く تعني أن تسحب.","N抜きでV, N抜きのN, N抜きにして। 冗談・朝食・本人-এর মতো যা সচরাচর থাকত সেটি intentionally omit।":"N抜きでV، N抜きのN، N抜きにして. حذف متعمد لشيء كان سيكون موجودا عادة، مثل 冗談・朝食・本人.","～なしで সাধারণ absence; ～抜きで deliberate exclusion এবং একটু formal/idiomatic। 人なしでも possible, 人抜きで meeting = তাকে বাদ দিয়ে।":"～なしで = غياب عام؛ ～抜きで = استبعاد متعمد، رسمي/اصطلاحي قليلا. 人なしでも ممكن؛ اجتماع 人抜きで = عقد الاجتماع بدون ذلك الشخص.","Sandwich থেকে একটি ingredient টেনে “抜き” করে বের করো—N抜き。":"اسحب مكونا واحدا من الساندويتش — «抜き» — N抜き.","মজা বাদ দিয়ে সিরিয়াসভাবে কথা বলতে বলো—冗談抜きで।":"اطلب من شخص أن يتحدث بجدية، دون مزاح — 冗談抜きで.","অনুভূতি, শারীরিক অবস্থা বা ইচ্ছা এত প্রবল যে নিয়ন্ত্রণ/উপেক্ষা করা যায় না: “ভীষণ…/সহ্য হয় না।”":"شعور، أو حالة جسدية، أو رغبة قوية جدا لدرجة أنه لا يمكن السيطرة عليها أو تجاهلها: «بشكل فظيع… / لا يُطاق».","Vたくて／いAくて／なAで＋しょうがない・しかたがない। Intentional action নয়; uncontrollable feeling। Formalভাবে ～てなりません-ও আছে।":"Vたくて / いAくて / なAで + しょうがない・しかたがない. ليس فعلا مقصودا؛ شعور لا يمكن السيطرة عليه. رسميا، توجد أيضا ～てなりません.","～ずにはいられない-এ feeling action করায়; ～てしょうがない-এ feeling/state নিজেই অসহনীয়। しかたがない প্রায় সমার্থক।":"مع ～ずにはいられない، الشعور يجعلك تفعل؛ مع ～てしょうがない، الشعور/الحالة نفسه لا يُطاق. しかたがない مرادفة تقريبا.","Feeling meter MAX-এ আটকে গেছে—“কিছু করার উপায় নেই” = しょうがない。":"عداد الشعور عالق عند MAX — «لا يوجد شيء يمكنني فعله حيال ذلك» = しょうがない.","পরিবারকে দেখতে খুব ইচ্ছে করছে—会いたくてしょうがない দিয়ে বলো।":"قل «أفتقد عائلتي بشكل فظيع / أريد حقا رؤيتهم» باستخدام 会いたくてしょうがない.","TRY! N3 — প্রতিটি Rule একবার বুঝে সারাজীবন মনে রাখো":"TRY! N3 — افهم كل قاعدة مرة واحدة وتذكرها مدى الحياة","১১৩টি Grammar • Rule-specific গভীর ব্যাখ্যা • সূক্ষ্ম ব্যবহার • confusing “VS” • মনে রাখার ছবি • ১,১৩০টি উদাহরণ":"113 نقطة قواعد • شروحات عميقة خاصة بكل قاعدة • تفاصيل استخدام دقيقة • مقارنات «VS» مربكة • صور ذاكرة • 1,130 مثالا","Rule-এর গভীর ব্যাখ্যা":"شرح عميق للقاعدة","একবার বুঝে সারাজীবন মনে রাখো":"افهم مرة واحدة، تذكر مدى الحياة","🧠 অর্থের মেরুদণ্ড":"🧠 العمود الفقري للمعنى","🎯 সূক্ষ্ম ব্যবহার":"🎯 نقاط دقيقة في الاستخدام","⚖️ সবচেয়ে বেশি গুলিয়ে যায়":"⚖️ الأكثر خلطا غالبا","🖼️ মনে রাখার ছবি":"🖼️ صورة ذاكرة","← আগের Part":"← الجزء السابق","সব Part-এর তালিকা":"قائمة كل الأجزاء","পরের Part →":"الجزء التالي →","Part 01 শুরু →":"ابدأ الجزء 01 →","N3 Grammar-এর সব ১১টি Part":"كل أجزاء قواعد N3 الـ 11","নিচের Part-গুলো ১ থেকে ১১ পর্যন্ত সম্পূর্ণ আছে। যেটি পড়বেন, সেটিতে tap করুন—শেষে আগের/পরের Part-এ যাওয়ার button-ও পাবেন।":"الأجزاء أدناه كاملة، من 1 إلى 11. اضغط على الجزء الذي تريد دراسته — في النهاية ستجد أيضا أزرارا للذهاب إلى الجزء السابق/التالي.","সব ১১৩টি Grammar দেখুন":"انظر كل نقاط القواعد الـ 113","আগের বা পরের Grammar Part":"جزء القواعد السابق أو التالي"},"frag":{},"patterns":[{"s":"{n} نقطة قواعد • تم تعلم {done}","t":"{n} نقطة قواعد • تم تعلم {done}"},{"s":"الجزء {cur} / {total} • كل الأجزاء","t":"الجزء {cur} / {total} • كل الأجزاء"},{"s":"{n} جزء • عودة إلى القائمة","t":"{n} جزء • عودة إلى القائمة"},{"s":"تم تعلم {done} / {total}","t":"تم تعلم {done} / {total}"},{"s":"تم تعلم {done} • تبقى {left}","t":"تم تعلم {done} • تبقى {left}"},{"s":"تم العثور على {n} نقطة قواعد","t":"تم العثور على {n} نقطة قواعد"}]};
(function () {
  var D = window.AponarN3Deep;
  if (!D || !D.map) return;
  var map = D.map, frag = D.frag || {};
  function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
  var pats = (D.patterns || []).slice().sort(function (a, b) { return b.s.length - a.s.length; }).map(function (p) {
    var names = [];
    var re = "^" + p.s.split(/(\{[A-Za-z]+\})/).map(function (seg) {
      var m = /^\{([A-Za-z]+)\}$/.exec(seg);
      if (m) { names.push(m[1]); return "([\\s\\S]*?)"; }
      return esc(seg);
    }).join("") + "$";
    return { re: new RegExp(re), names: names, t: p.t };
  });
  function fixValue(v) {
    if (typeof v !== "string" || !v) return v;
    if (Object.prototype.hasOwnProperty.call(map, v)) return map[v];
    if (Object.prototype.hasOwnProperty.call(frag, v)) return frag[v];
    for (var i = 0; i < pats.length; i++) {
      var m = pats[i].re.exec(v);
      if (m) {
        var caps = {};
        pats[i].names.forEach(function (n, j) { caps[n] = m[j + 1]; });
        return pats[i].t.replace(/\{([A-Za-z]+)\}/g, function (_, n) { return n in caps ? caps[n] : _; });
      }
    }
    return v;
  }
  var searchKeys = Object.keys(map).sort(function (a, b) { return b.length - a.length; });
  function fixRoot(root) {
    if (!root) return;
    var walker = document.createTreeWalker(root, 4, null);
    var texts = [], n;
    while ((n = walker.nextNode())) texts.push(n);
    for (var i = 0; i < texts.length; i++) {
      if (texts[i].parentNode && /^(SCRIPT|STYLE)$/.test(texts[i].parentNode.nodeName || "")) continue;
      var v = texts[i].nodeValue, nv = fixValue(v);
      if (nv !== v) texts[i].nodeValue = nv;
    }
    var els = root.querySelectorAll ? root.querySelectorAll("*") : [];
    for (var j = 0; j < els.length; j++) {
      var el = els[j];
      if (el.getAttribute) {
        var al = el.getAttribute("aria-label");
        if (al) { var na = fixValue(al); if (na !== al) el.setAttribute("aria-label", na); }
      }
      var ds = el.dataset && el.dataset.search;
      if (typeof ds === "string" && ds) {
        var out = ds;
        for (var q = 0; q < searchKeys.length; q++) {
          var k = searchKeys[q];
          if (out.indexOf(k) < 0) continue;
          var re = new RegExp("(?<![\\u0980-\\u09FF])" + esc(k) + "(?![\\u0980-\\u09FF])", "g");
          out = out.replace(re, function () { return map[k]; });
        }
        if (out !== ds) el.dataset.search = out;
      }
    }
  }
  var scheduled = false;
  function fixAll() { if (document.body) fixRoot(document.body); }
  function schedule() {
    if (scheduled) return;
    scheduled = true;
    setTimeout(function () { scheduled = false; fixAll(); }, 0);
  }
  function observe() {
    if (!window.MutationObserver || !document.body) return;
    new MutationObserver(schedule).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["aria-label", "data-search"] });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", function () { fixAll(); observe(); });
  else { fixAll(); observe(); }
  window.addEventListener("load", fixAll);
})();
